); font-weight: 900; font-style: italic;}@font-face{font-family: "Lato-BlaIta"; src: url("/web/static/fonts/./lato/Lato-BlaIta-webfont.eot"); src: url("/web/static/fonts/./lato/Lato-BlaIta-webfont.eot?#iefix") format("embedded-opentype"), url("/web/static/fonts/./lato/Lato-BlaIta-webfont.woff") format("woff"), url("/web/static/fonts/./lato/Lato-BlaIta-webfont.ttf") format("truetype"), url("/web/static/fonts/./lato/Lato-BlaIta-webfont.svg#Roboto") format("svg");}@font-face{font-family: "Montserrat"; src: url("/web/static/fonts/./google/Montserrat/Montserrat-Regular.ttf") format("truetype"); font-weight: 400; font-style: normal;}@font-face{font-family: "Open_Sans"; src: url("/web/static/fonts/./google/Open_Sans/Open_Sans-Regular.ttf") format("truetype"); font-weight: 400; font-style: normal;}@font-face{font-family: "Oswald"; src: url("/web/static/fonts/./google/Oswald/Oswald-Regular.ttf") format("truetype"); font-weight: 400; font-style: normal;}@font-face{font-family: "Raleway"; src: url("/web/static/fonts/./google/Raleway/Raleway-Regular.ttf") format("truetype"); font-weight: 400; font-style: normal;}@font-face{font-family: "Roboto"; src: url("/web/static/fonts/./google/Roboto/Roboto-Regular.ttf") format("truetype"); font-weight: 400; font-style: normal;}@font-face{font-family: "Tajawal"; src: url("/web/static/fonts/./google/Tajawal/Tajawal-Regular.ttf") format("truetype"); font-weight: 400; font-style: normal;}@font-face{font-family: "Fira_Mono"; src: url("/web/static/fonts/./google/Fira_Mono/Fira_Mono-Regular.ttf") format("truetype"); font-weight: 400; font-style: normal;}\n/* /web/static/src/scss/ui.scss */\n :root .o_hidden{display: none !important;}.o_disabled{pointer-events: none; opacity: 0.5;}.o_btn_loading{opacity: 0.5;}.o_btn_loading .fa:not(.fa-spin){display: none;}.o_text_overflow{display: inline-block; max-width: 100%; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; vertical-align: top;}.dropdown-menu{max-height: 70vh; overflow: auto; background-clip: border-box;}.dropdown-menu:not(.o-hb-select-dropdown){scrollbar-width: thin;}.dropdown-toggle{white-space: nowrap;}.dropdown-toggle.o-no-caret::before, .dropdown-toggle.o-no-caret::after{content: normal;}.o_catch_attention{position: relative; z-index: 1; animation: catchAttention 200ms ease 0s infinite normal;}.o_treeEntry{padding-left: var(--treeEntry-padding-h, 24px); position: relative;}.o_treeEntry:before, .o_treeEntry:after{position: absolute; left: var(--treeEntry--beforeAfter-left, calc(var(--treeEntry-padding-h, 24px) * .5)); background: var(--treeEntry--beforeAfter-color, #dee2e6); content: '';}.o_treeEntry:before{top: var(--treeEntry--before-top, 0); width: 1px; height: 100%;}.o_treeEntry:after{display: var(--treeEntry--after-display, initial); top: calc(.5em + var(--treeEntry-padding-v, 8px)); width: var(--treeEntry--after-width, calc(var(--treeEntry-padding-h, 24px) * .5)); height: 1px;}.o_treeEntry:last-of-type:before{height: calc(.5em + var(--treeEntry-padding-v, 8px));}@keyframes catchAttention{0%, 20%, 40%, 60%, 80%, 100%{transition-timing-function: cubic-bezier(0.215, 0.61, 0.355, 1);}0%{transform: translateY(-30%);}20%{transform: translateY(-25%);}40%{transform: translateY(-20%);}60%{transform: translateY(-15%);}80%{transform: translateY(-10%);}100%{transform: translateY(-5%);}}span.o_force_ltr{display: inline;}.o_force_ltr{unicode-bidi: embed; direction: ltr;}.o_image_24_cover{width: 24px; height: 24px; object-fit: cover;}.o_image_40_cover{width: 40px; height: 40px; object-fit: cover;}.o_image_64_cover{width: 64px; height: 64px; object-fit: cover;}.o_image_64_contain{width: 64px; height: 64px; object-fit: contain;}.o_image_64_max{max-width: 64px; max-height: 64px;}.modal .o_cp_action_menus .o-dropdown:has(.fa-cog){display: none;}.o_ui_app_icon{width: var(--oi-font-size, 1em);}:not(:hover) > .o_ui_app_icon{--oi-color: currentColor;}.o_button_area{position: absolute; top: 0; left: 0; bottom: 0; right: 0;}.o_btn_reset{appearance: none; margin: unset; padding: unset; background: unset; border: unset; font-family: inherit; font-size: 100%;}\n/* /point_of_sale/static/src/app/components/accordion_item/accordion_item.scss */\n .accordion.disabled{pointer-events: none; opacity: 0.5;}.accordion-header{margin-left: 1px;}.accordion-header:not(.no-caret){display: flex; align-items: center; gap: 5px;}.accordion-header:not(.no-caret):before{content: "\\f0d7"; font-family: FontAwesome; display: inline-block; transform: rotate(-90deg); transition: .25s ease-in-out;}.accordion-header:not(.no-caret).open:before{transform: rotate(0deg);}.accordion-content-container{overflow: auto; transition: max-height 0.25s ease-in-out; -ms-overflow-style: none; scrollbar-width: none;}.accordion-content-container::-webkit-scrollbar{display: none;}\n/* /point_of_sale/static/src/app/components/buttons/quantity_buttons/quantity_buttons.scss */\n input[name="pos_quantity"]{padding: 0;}@media (max-width: 767.98px){input[name="pos_quantity"]{max-width: 3rem;}}@media (min-width: 768px){input[name="pos_quantity"]{max-width: 4rem;}}input[name="pos_quantity"]::-webkit-outer-spin-button, input[name="pos_quantity"]::-webkit-inner-spin-button{-webkit-appearance: none; margin: 0;}input[name="pos_quantity"][type=number]{-moz-appearance: textfield;}.px-2-5{padding-right: 0.75rem !important; padding-left: 0.75rem !important;}\n/* /point_of_sale/static/src/app/components/category_selector/category_selector.scss */\n .category-list{grid-template-columns: repeat(auto-fill, minmax(115px, 1fr)); overflow-y: auto; flex-shrink: 0; margin-bottom: 8px; max-height: 16.5rem;}@media (max-width: 767.98px){.category-list{max-height: 11rem;}}.category-button{--btn-border-color: #e9ecef; border-width: 2px; height: 4rem;}.category-button .line-clamp-3{display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden;}\n/* /point_of_sale/static/src/app/components/loader/loader.scss */\n .pos-loader{background-color: #222; position: abso