oup>\n                            <field name="parent_id" widget="res_partner_many2one" placeholder="Company Name..." string="Company" domain="[('is_company', '=', True)]" context="{'default_is_company': True, 'default_user_id': user_id, 'show_address': False}" invisible="((is_company and not parent_id) or company_name) and company_name != ''"/>\n                            <div colspan="2" class="d-flex gap-2" invisible="not company_name or company_name == '' or is_company">\n                                <label for="company_name" class="fw-bold text-nowrap"/>\n                                <field name="company_name"/>\n                                <button name="create_company" icon="fa-plus-square" string="Create" type="object" class="oe_edit_only btn-link text-nowrap"/>\n                            </div>\n                            <span class="o_form_label o_td_label o_address_type" name="address_name">\n                                <field name="type_address_label" invisible="is_company" readonly="1" class="fw-bold"/>\n                                <span invisible="not is_company">Address</span>\n                            </span>\n                            <div class="o_address_format">\n                                <field name="street" placeholder="Street..." class="o_address_street"/>\n                                <field name="street2" placeholder="Street 2..." class="o_address_street"/>\n                                <field name="city" placeholder="City" class="o_address_city"/>\n                                <field name="state_id" placeholder="State" class="o_address_state" options="{'no_open': True, 'no_quick_create': True}" context="{'country_id': country_id, 'default_country_id': country_id, 'zip': zip}"/>\n                                <field name="zip" placeholder="ZIP" class="o_address_zip"/>\n                                <div name="partner_address_country" class="d-flex justify-content-between">\n                      