widget=\\"upgrade_boolean\\"/>\\n                        </setting>\\n                        <setting id=\\"shipping_costs_easypost\\" help=\\"Compute shipping costs and ship with Easypost\\" documentation=\\"/applications/inventory_and_mrp/inventory/shipping/setup/third_party_shipper.html\\">\\n                            <field name=\\"module_delivery_easypost\\" widget=\\"upgrade_boolean\\"/>\\n                        </setting>\\n                        <setting id=\\"shipping_costs_sendcloud\\" help=\\"Compute shipping costs and ship with Sendcloud\\" documentation=\\"/applications/inventory_and_mrp/inventory/shipping/setup/third_party_shipper.html\\">\\n                            <field name=\\"module_delivery_sendcloud\\" widget=\\"upgrade_boolean\\"/>\\n                        </setting>\\n                        <setting id=\\"shipping_costs_shiprocket\\" help=\\"Compute shipping costs and ship with Shiprocket\\" documentation=\\"/applications/inventory_and_mrp/inventory/shipping/setup/third_party_shipper.html\\">\\n                            <field name=\\"module_delivery_shiprocket\\" widget=\\"upgrade_boolean\\"/>\\n                        </setting>\\n                        <setting id=\\"shipping_costs_starshipit\\" help=\\"Compute shipping costs and ship with Starshipit\\" documentation=\\"/applications/inventory_and_mrp/inventory/shipping/setup/third_party_shipper.html\\">\\n                            <field name=\\"module_delivery_starshipit\\" widget=\\"upgrade_boolean\\"/>\\n                        </setting>\\n                        <setting id=\\"shipping_costs_envia\\" help=\\"Compute shipping costs and ship with Envia.com\\" documentation=\\"/applications/inventory_and_mrp/inventory/shipping/setup/third_party_shipper.html\\">\\n                            <field name=\\"module_delivery_envia\\" widget=\\"upgrade_boolean\\"/>\\n                        </setting>\\n                    </block>\\n                    <block title=\\"Invoicing\\" name=\\"invoicing_setting_container\\">\\n                        <setting id=\\"sales_settings_invoicing_policy\\" title=\\"This default value is applied to any new product created. This can be changed in the product detail form.\\" documentation=\\"/applications/sales/sales/invoicing/invoicing_policy.html\\" help=\\"Quantities to invoice from sales orders\\">\\n                            <field name=\\"default_invoice_policy\\" class=\\"o_light_label\\" widget=\\"radio\\"/>\\n                        </setting>\\n                        <setting id=\\"automatic_invoicing\\" help=\\"Generate the invoice automatically when the online payment is confirmed\\" invisible=\\"default_invoice_policy != 'order' or not portal_confirmation_pay\\">\\n                            <field name=\\"automatic_invoice\\"/>\\n                            <div invisible=\\"not automatic_invoice\\" groups=\\"base.group_no_one\\">\\n                                <label for=\\"invoice_mail_template_id\\" class=\\"o_light_label me-2\\"/>\\n                                <field name=\\"invoice_mail_template_id\\" class=\\"oe_inline\\" options=\\"{'no_create': True}\\"/>\\n                            </div>\\n                        </setting>\\n                        <setting id=\\"setting_commission\\" help=\\"Manage Sales &amp; teams targets and commissions\\">\\n                            <field name=\\"module_sale_commission\\" widget=\\"upgrade_boolean\\"/>\\n                        </setting>\\n                    </block>\\n                    <block title=\\"Connectors\\" id=\\"connectors_setting_container\\">\\n                        <setting id=\\"amazon_connector\\" documentation=\\"/applications/sales/sales/amazon_connector/setup.html\\" help=\\"Import Amazon orders and sync deliveries\\">\\n                            <field name=\\"module_sale_amazon\\" widget=\\"upgrade_boolean\\"/>\\n                            <div class=\\"content-group\\" name=\\"amazon_connector\\" invisible=\\"not module_sale_amazon\\"/>\\n                        </setting>\\n                        <setting id=\\"gelato\\" documentation=\\"/applications/sales/sales/gelato.html\\" help=\\"Place orders through Gelato's print-on-demand service\\">\\n                            <field name=\\"module_sale_gelato\\"/>\\n                            <div class=\\"content-group\\" name=\\"gelato_credentials\\" invisible=\\"not module_sale_gelato\\"/>\\n                        </setting>\\n                        <setting id=\\"shopee_connector\\" help=\\"Import Shopee orders and sync deliveries\\">\\n                            <field name=\\"module_sale_shopee\\" widget=\\"upgrade_boolean\\"/>\\n                        </setting>\\n                    </block>\\n                </app>\\n            </xpath>", "es_ES": "<xpath expr=\\"//form\\" position=\\"inside\\">\\n                <app notApp=\\"1\\" string=\\"Ventas\\" data-string=\\"Sales\\" name=\\"sale_management\\" groups=\\"sales_team.group_sale_manager\\">\\n                    <block title=\\"Catálogo de productos\\" name=\\"catalog_setting_container\\">\\n                        <setting id=\\"variant_options\\" help=\\"Vende variantes de un producto utilizando atributos (tamaño, color, etc.)\\" documentation=\\"/applications/sales/sales/products_prices/products/variants.html\\">\\n                            <field name=\\"group_product_variant\\"/>\\n                            <div class=\\"content-group\\" invisible=\\"not group_product_variant\\">\\n                                <div class=\\"mt8\\">\\n                                    <button name=\\"179\\" icon=\\"oi-arrow-right\\" type=\\"action\\" string=\\"Atributos\\" class=\\"btn-link\\"/>\\n                                </div>\\n                            </div>\\n                        </setting>\\n                        <setting string=\\"Entrada de cuadrícula de variante\\" help=\\"Añada varias variantes a un pedido desde una