         <span t-elif=\\"mo.state in ['progress']\\" class=\\"small badge text-bg-warning orders_label_text_align\\">\\n                                <i class=\\"fa fa-fw fa-clock-o\\"/> <b>In progress</b>\\n                            </span>\\n                        </div>\\n                    </t>\\n                </div>\\n            </t>\\n        </xpath>\\n    </data>", "es_ES": "<data name=\\"Orders MOs\\" inherit_id=\\"sale.sale_order_portal_content\\">\\n        <xpath expr=\\"//div[@id='informations']\\" position=\\"inside\\">\\n            <t t-set=\\"mrp_productions\\" t-value=\\"sale_order.mrp_production_ids\\"/>\\n            <t t-if=\\"mrp_productions\\">\\n                <div>\\n                    <strong>Órdenes de fabricación</strong>\\n                </div>\\n                <div>\\n                    <t t-foreach=\\"mrp_productions\\" t-as=\\"mo\\">\\n                        <div class=\\"d-flex flex-wrap align-items-center justify-content-between\\">\\n                            <div>\\n                                <span t-out=\\"mo.name\\"/>\\n                                <div class=\\"small d-lg-inline-block ms-3\\">\\n                                    Fecha:\\n                                    <span class=\\"text-muted\\" t-field=\\"mo.date_finished\\" t-options=\\"{'date_only': True}\\"/>\\n                                </div>\\n                            </div>\\n                            <span t-if=\\"mo.state in ['to_close', 'done']\\" class=\\"small badge text-bg-success orders_label_text_align\\">\\n                                <i class=\\"fa fa-fw fa-check\\"/> <b>Fabricado</b>\\n                            </span>\\n                            <span t-elif=\\"mo.state == 'cancel'\\" class=\\"small badge text-bg-danger orders_label_text_align\\">\\n                                <i class=\\"fa fa-fw fa-times\\"/> <b>Cancelado</b>\\n                            </span>\\n                            <span t-elif=\\"mo.state in ['confirmed']\\" class=\\"small badge text-bg-info orders_label_text_align\\">\\n                                <i class=\\"fa fa-fw fa-clock-o\\"/> <b>Confirmado</b>\\n                            </span>\\n                            <span t-elif=\\"mo.state in ['progress']\\" class=\\"small badge text-bg-warning orders_label_text_align\\">\\n                                <i class=\\"fa fa-fw fa-clock-o\\"/> <b>En proceso</b>\\n                            </span>\\n                        </div>\\n                    </t>\\n                </div>\\n            </t>\\n        </xpath>\\n    </data>"}	<?xml version="1.0"?>\n<data name="Orders MOs" inherit_id="sale.sale_order_portal_content">\n        <xpath expr="//div[@id='informations']" position="inside">\n            <t t-set="mrp_productions" t-value="sale_order.mrp_production_ids"/>\n            <t t-if="mrp_productions">\n                <div>\n                    <strong>Manufacturing Orders</strong>\n                </div>\n                <div>\n                    <t t-foreach="mrp_productions" t-as="mo">\n                        <div class="d-flex flex-wrap align-items-center justify-content-between">\n                            <div>\n                                <span t-out="mo.name"/>\n                                <div class="small d-lg-inline-block ms-3">\n                                    Date:\n                                    <span class="text-muted" t-field="mo.date_finished" t-options="{'date_only': True}"/>\n                                </div>\n                            </div>\n                            <span t-if="mo.state in ['to_close', 'done']" class="small badge text-bg-success orders_label_text_align">\n                                <i class="fa fa-fw fa-check"/> <b>Manufactured</b>\n                            </span>\n                            <span t-elif="mo.state == 'cancel'" class="small badge text-bg-danger orders_label_text_align">\n                                <i class="fa fa-fw fa-times"/> <b>Cancelled</b>\n                            </span>\n                            <span t-elif="mo.state in ['confirmed']" class="small badge text-bg-info orders_label_text_align">\n                                <i class="fa fa-fw fa-clock-o"/> <b>Confirmed</b>\n                            </span>\n                            <span t-elif="mo.state in ['progress']" class="small badge text-bg-warning orders_label_text_align">\n                                <i class="fa fa-fw fa-clock-o"/> <b>In progress</b>\n                            </span>\n                        </div>\n                    </t>\n                </div>\n            </t>\n        </xpath>\n    </data>\n\n	f	t	2026-11-25 09:11:15.760375	2026-11-25 09:11:15.760375	f	\N	\N	\N	\N	\N	\N	\N	\N	\N	f	f
