 support_express_checkout\\"/>\\n                                </group>\\n                                <group string=\\"Disponibilidad\\" name=\\"availability\\">\\n                                    <field name=\\"maximum_amount\\"/>\\n                                    <label for=\\"available_currency_ids\\" groups=\\"base.group_system\\"/>\\n                                    <!-- Use `o_row` to allow placing a button next to the field in overrides. -->\\n                                    <div name=\\"available_currencies\\" class=\\"o_row\\" groups=\\"base.group_system\\">\\n                                        <field name=\\"available_currency_ids\\" widget=\\"many2many_tags\\" placeholder=\\"Seleccione las monedas. Déjelo vacío para no restringir ninguna.\\" options=\\"{'no_create': True}\\"/>\\n                                    </div>\\n                                    <field name=\\"available_country_ids\\" widget=\\"many2many_tags\\" placeholder=\\"Seleccione sus países. Deje vacío para estar disponible en todas partes.\\" options=\\"{'no_create': True}\\"/>\\n                                </group>\\n                                <group string=\\"Seguimiento de pagos\\" name=\\"payment_followup\\" invisible=\\"1\\"/>\\n                            </group>\\n                        </page>\\n                        <page string=\\"Mensajes\\" name=\\"messages\\" invisible=\\"module_id and module_state != 'installed'\\">\\n                            <group>\\n                                <field name=\\"pre_msg\\"/>\\n                                <field name=\\"pending_msg\\"/>\\n                                <field name=\\"auth_msg\\" invisible=\\"not support_manual_capture\\"/>\\n                                <field name=\\"done_msg\\"/>\\n                                <field name=\\"cancel_msg\\"/>\\n                            </group>\\n                        </page>\\n                    </notebook>\\n                <