led'">\n                                            <i class="oi oi-fw o_button_icon oi-arrow-right"/>\n                                            Enable Payment Methods\n                                        </a>\n                                    </div>\n                                    <field name="allow_tokenization" invisible="not support_tokenization"/>\n                                    <field name="capture_manually" invisible="not support_manual_capture"/>\n                                    <field name="allow_express_checkout" invisible="not support_express_checkout"/>\n                                </group>\n                                <group string="Availability" name="availability">\n                                    <field name="maximum_amount"/>\n                                    <label for="available_currency_ids" groups="base.group_system"/>\n                                    <!-- Use `o_row` to allow placing a button next to the field in overrides. -->\n                                    <div name="available_currencies" class="o_row" groups="base.group_system">\n                                        <field name="available_currency_ids" widget="many2many_tags" placeholder="Select currencies. Leave empty not to restrict any." options="{'no_create': True}"/>\n                                    </div>\n                                    <field name="available_country_ids" widget="many2many_tags" placeholder="Select countries. Leave empty to make available everywhere." options="{'no_create': True}"/>\n                                </group>\n                                <group string="Payment Followup" name="payment_followup" invisible="1"/>\n                            </group>\n                        </page>\n                        <page string="Messages" name="messages" invisible="module_id and module_state != 'installed'">\n                            <group>\n                                <field name="pre_msg"/>\n