', 'purchase')\\">\\n                                        <field name=\\"display_alias_fields\\" invisible=\\"1\\"/>\\n                                        <div class=\\"o_row\\" colspan=\\"2\\" invisible=\\"display_alias_fields\\">\\n                                            <a type=\\"action\\" name=\\"219\\" class=\\"btn btn-link\\" role=\\"button\\">\\n                                                <i class=\\"oi oi-fw o_button_icon oi-arrow-right\\"/> Configurar dominio de alias\\n                                            </a>\\n                                        </div>\\n                                        <div class=\\"o_row\\" colspan=\\"2\\" dir=\\"ltr\\" invisible=\\"not display_alias_fields\\">\\n                                            <label string=\\"Alias de correo electrónico\\" for=\\"alias_name\\"/>\\n                                            <field name=\\"alias_name\\" placeholder=\\"alias\\"/>@\\n                                            <field name=\\"alias_domain_id\\" placeholder=\\"p. ej., miempresa.com\\" options=\\"{'no_create': True, 'no_open': True}\\"/>\\n                                        </div>\\n                                        <field name=\\"incoming_einvoice_notification_email\\" placeholder=\\"p. ej., finanzas@ejemplo.com; contabilidad@ejemplo.com\\" class=\\"w-100\\"/>\\n                                    </group>\\n                                    <!-- edi -->\\n                                    <group name=\\"group_edi_config\\" string=\\"Intercambio electrónico de datos (EDI)\\" invisible=\\"1\\"/>\\n                                    <group string=\\"Comunicaciones de pago\\" invisible=\\"type != 'sale'\\">\\n                                        <field name=\\"invoice_reference_type\\"/>\\n                                        <field name=\\"invoice_reference_model\\" invisible=\\"invoice_reference_type == 'none'\\"/>\\n                                    </group>\\n         