 o_stat_info">\n                                    <field name="reconciled_statement_lines_count"/>\n                                    <span class="o_stat_text">Transaction</span>\n                                </div>\n                            </button>\n\n                            <!-- Journal Entry  button -->\n                            <button name="button_open_journal_entry" type="object" class="oe_stat_button" icon="fa-bars" invisible="not move_id" groups="account.group_account_user,account.group_account_readonly">\n                                <div class="o_stat_info">\n                                    <span class="o_stat_text">Journal Entry</span>\n                                </div>\n                            </button>\n                        </div>\n\n                        <widget name="web_ribbon" text="Invoicing App Legacy" bg_color="text-bg-info" invisible="state != 'invoicing_legacy'" tooltip="This payment has been generated through the Invoicing app, before installing Accounting. It has been disabled by the 'Invoicing Switch Threshold Date' setting so that it does not impact your accounting."/>\n\n                        <div class="oe_title">\n                            <h1 invisible="state != 'draft'"><span>Draft</span></h1>\n                            <h1 invisible="state == 'draft'"><field name="name" readonly="1"/></h1>\n                        </div>\n\n                        <group name="main_group">\n                            <group name="group1">\n                                <field name="payment_type" widget="radio" options="{'horizontal': True}" readonly="state != 'draft'"/>\n                                <field name="partner_id" context="{'default_is_company': True}" string="Customer" options="{'no_quick_create': True}" invisible="partner_type != 'customer'" readonly="state != 'draft'"/>\n                                <field name="partner_id" context="{'default_is_company': True}" string="Vendor" option