get&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}\\" name=\\"purchase_shipping_address\\"/>\\n                <div>\\n                    <strong>Fecha de envío solicitada:</strong>\\n                    <span t-field=\\"o.date_planned\\" t-options=\\"{'date_only': 'true'}\\"/>\\n                </div>\\n            </t>\\n        </t>\\n        <div class=\\"page\\">\\n            <div class=\\"oe_structure\\"/>\\n            <t t-set=\\"layout_document_title\\">\\n                <span>Solicitud de presupuesto <span t-field=\\"o.name\\"/></span>\\n            </t>\\n\\n            <table class=\\"table table-borderless\\">\\n                <thead style=\\"display: table-row-group\\">\\n                    <tr>\\n                        <th name=\\"th_description\\"><strong>Descripción</strong></th>\\n                        <th name=\\"th_expected_date\\" class=\\"text-center\\"><strong>Fecha prevista</strong></th>\\n                        <th name=\\"th_quantity\\" class=\\"text-end\\"><strong>Ctd.</strong></th>\\n                    </tr>\\n                </thead>\\n                <tbody>\\n                    <t t-foreach=\\"o.order_line.filtered(lambda l: l.display_type or l.product_qty != 0)\\" t-as=\\"order_line\\">\\n                        <tr t-att-class=\\"'fw-bolder o_line_section' if order_line.display_type == 'line_section' else 'fw-bold o_line_subsection' if order_line.display_type == 'line_subsection' else 'fst-italic o_line_note' if order_line.display_type == 'line_note' else ''\\">\\n                            <t t-if=\\"not order_line.display_type\\">\\n                                <td id=\\"product\\">\\n                                    <span t-field=\\"order_line.name\\"/>\\n                                </td>\\n                                <td class=\\"text-center\\">\\n                                    <s