ppol connection.-->\\n                            <div invisible=\\"not peppol_use_parent_company\\" class=\\"mt-2\\">\\n                                <button string=\\"Disconnect\\" name=\\"button_peppol_disconnect_branch_from_parent\\" type=\\"object\\" class=\\"btn-secondary me-1\\"/>\\n                            </div>\\n                        </div>\\n                    </div>\\n                    <div class=\\"row mb-3\\" invisible=\\"not account_is_token_out_of_sync\\">\\n                        <div class=\\"content-group\\">\\n                            Your Peppol identification is:\\n                            <field name=\\"account_peppol_edi_identification\\" nolabel=\\"1\\"/>\\n                        </div>\\n                        <div class=\\"content-group mt-3 alert alert-danger\\" role=\\"alert\\">\\n                            <div class=\\"d-flex align-items-start\\">\\n                                <i class=\\"fa fa-exclamation-triangle fa-lg me-3 mt-1\\" aria-hidden=\\"true\\"/>\\n                                <div>\\n                                    <span><strong>Disconnected from Peppol!</strong></span>\\n                                    <p>\\n                                        Your database is not linked to Peppol anymore. This might be due to a database duplication or restoration.\\n                                        <br/><a class=\\"text-info\\" href=\\"https://www.odoo.com/help-form\\" target=\\"_blank\\"><strong>Contact us</strong></a>\\n                                        to reconnect your database to Peppol.\\n                                    </p>\\n                                </div>\\n                            </div>\\n\\n                            <!-- hidden for now until a proper fix is in place, buttons were not removed as we will need them later-->\\n                            <div class=\\"mt-3 d-flex gap-1\\" invisible=\\"True\\">\\n                                <button name=\\"button_reconnect_this_database\\" type=\\"object\\" string=\\"Reconnect this database\\" class=\\"btn btn-primary\\" icon=\\"fa-refresh\\"/>\\n                                <button name=\\"button_disconnect_this_database\\" type=\\"object\\" string=\\"Disconnect this database\\" class=\\"btn btn-danger\\" icon=\\"fa-unlink\\"/>\\n                            </div>\\n                        </div>\\n                    </div>\\n                </setting>\\n                <setting invisible=\\"account_is_token_out_of_sync or peppol_use_parent_company or peppol_participation_role != 'sending_and_receiving'\\">\\n                    <div class=\\"row\\" name=\\"peppol_journal_config\\">\\n                        <label string=\\"Incoming Accounting Journal\\" for=\\"account_peppol_purchase_journal_id\\" class=\\"col-lg-5\\"/>\\n                        <field name=\\"account_peppol_purchase_journal_id\\" class=\\"col-lg-7\\" required=\\"peppol_purchase_journal_required\\"/>\\n                    </div>\\n                </setting>\\n            </xpath>", "es_ES": "<xpath expr=\\"//div[@id='account_peppol_install']\\" position=\\"replace\\">\\n                <setting id=\\"account_peppol\\" help=\\"Permita que se envíen y reciban facturas a través de la red de Peppol\\">\\n                    <div invisible=\\"account_is_token_out_of_sync\\">\\n                        <!-- Info in case of sender. -->\\n                        <div invisible=\\"peppol_use_parent_company or account_peppol_proxy_state != 'sender'\\">\\n                            Tu ID de PEPPOL <field name=\\"account_peppol_edi_identification\\" class=\\"oe_inline o_form_label\\" readonly=\\"1\\"/>.\\n                            <span class=\\"ps-2\\" invisible=\\"account_peppol_edi_mode == 'prod'\\">\\n                                (<field class=\\"oe_inline o_form_label text-uppercase\\" name=\\"account_peppol_edi_mode\\"/>)\\n                            </span>\\n                            <br/>\\n