eld name=\\"company_id\\" optional=\\"show\\" groups=\\"base.group_multi_company\\"/>\\n                    <field name=\\"qty_ordered\\" optional=\\"hide\\" sum=\\"Suma de la ctd. pedida\\"/>\\n                    <field name=\\"qty_received\\" optional=\\"hide\\" sum=\\"Suma de la cantidad recibida\\"/>\\n                    <field name=\\"qty_billed\\" optional=\\"hide\\" sum=\\"Suma de la cant. facturada\\"/>\\n                    <field name=\\"currency_id\\" optional=\\"show\\" column_invisible=\\"True\\"/>\\n                    <field name=\\"untaxed_total\\" optional=\\"hide\\" widget=\\"monetary\\" sum=\\"Suma del importe base total\\"/>\\n                    <field name=\\"price_total\\" optional=\\"show\\" widget=\\"monetary\\" sum=\\"Suma del total\\"/>\\n                    <field name=\\"state\\" optional=\\"show\\"/>\\n                </list>"}	<?xml version="1.0"?>\n<list string="Purchase Analysis">\n                    <field name="date_order"/>\n                    <field name="order_id" optional="show"/>\n                    <field name="partner_id" optional="show"/>\n                    <field name="product_id" optional="show"/>\n                    <field name="category_id" optional="show"/>\n                    <field name="user_id" optional="show" widget="many2one_avatar_user"/>\n                    <field name="company_id" optional="show" groups="base.group_multi_company"/>\n                    <field name="qty_ordered" optional="hide" sum="Sum of Qty Ordered"/>\n                    <field name="qty_received" optional="hide" sum="Sum of Qty Received"/>\n                    <field name="qty_billed" optional="hide" sum="Sum of Qty Billed"/>\n                    <field name="currency_id" optional="show" column_invisible="True"/>\n                    <field name="untaxed_total" optional="hide" widget="monetary" sum="Sum of Untaxed Total"/>\n                    <field name="price_total" optional="show" widget="monetary" sum="Sum of Total"/>\n     