2582	25	2535	1	1	res.config.settings.view.form.inherit.purchase	res.config.settings	\N	form	purchase_stock/views/res_config_settings_views.xml	extension	{"en_US": "<xpath expr=\\"//app[@name='purchase']\\" position=\\"inside\\">\\n\\t\\t\\t\\t<field name=\\"is_installed_sale\\" invisible=\\"1\\"/>\\n\\t\\t\\t\\t<block title=\\"Logistics\\" invisible=\\"not is_installed_sale\\" name=\\"request_vendor_setting_container\\">\\n\\t\\t\\t\\t\\t<setting title=\\"This adds a dropshipping route to apply on products in order to request your vendors to deliver to your customers. A product to dropship will generate a purchase request for quotation once the sales order confirmed. This is a on-demand flow. The requested delivery address will be the customer delivery address and not your warehouse.\\" help=\\"Request your vendors to deliver to your customers\\" documentation=\\"/applications/inventory_and_mrp/inventory/shipping/operation/dropshipping.html\\">\\n\\t\\t\\t\\t\\t\\t<field name=\\"module_stock_dropshipping\\"/>\\n\\t\\t\\t\\t\\t</setting>\\n\\t\\t\\t\\t\\t<setting title=\\"This adds a Replenish On Order (MTO) route to apply on products in order to generate on-demand replenishment linked to your sales orders (for example) as soon as they are confirmed, with a direct link. Purchase orders, manufacturing orders, etc. are triggered based on what way to replenish is set on the product (Buy or Manufacture route).\\" help=\\"Allow Make to Order, or automate PO, when a product is sold and get direct links between documents.\\" documentation=\\"/applications/inventory_and_mrp/inventory/warehouses_storage/replenishment/mto.html\\" groups=\\"stock.group_stock_manager\\">\\n                        \\t\\t\\t<field name=\\"replenish_on_order\\"/>\\n                    \\t\\t\\t</setting>\\n\\t\\t\\t\\t</block>\\n\\t\\t\\t</xpath>", "es_ES": "<xpath expr=\\"//app[@name='purchase']\\" position=\\"inside\\">\\n\\t\\t\\t\\t<field name=\\"is_installed_sale\\" invisible=\\"1\\"/>\\n\\t\\t\\t\\t<block title=\\"Logística\\" invisible=\\"not is_installed_sale\\" name=\\"request_vendor_setting_container\\">\\n\\t\\t\\t\\t\\t<setting title=\\"Esto añade una ruta de dropshipping aplicable a productos con el fin de solicitar a sus proveedores que entreguen directamente a sus clientes. Un producto para dropship generará una solicitud de presupuesto de compra una vez que se confirme el pedido de venta. Este es un flujo bajo demanda. La dirección de entrega solicitada será la dirección de entrega del cliente y no su almacén.\\" help=\\"Solicite a sus proveedores que entreguen a sus clientes\\" documentation=\\"/applications/inventory_and_mrp/inventory/shipping/operation/dropshipping.html\\">\\n\\t\\t\\t\\t\\t\\t<field name=\\"module_stock_dropshipping\\"/>\\n\\t\\t\\t\\t\\t</setting>\\n\\t\\t\\t\\t\\t<setting title=\\"Esto añade una ruta de reposición bajo pedido (fabricación sobre pedido) que se aplica a los productos para generar reposiciones bajo demanda vinculadas a sus pedidos de venta (por ejemplo) tan pronto como se confirman, con un enlace directo. Los pedidos de compra, las órdenes de fabricación, etc. se activan en función de la forma de reposición establecida en el producto (ruta de compra o fabricación).\\" help=\\"Permita la fabricación sobre pedido o automatice los pedidos de compra cuando se venda un producto y obtenga enlaces directos entre documentos.\\" documentation=\\"/applications/inventory_and_mrp/inventory/warehouses_storage/replenishment/mto.html\\" groups=\\"stock.group_stock_manager\\">\\n                        \\t\\t\\t<field name=\\"replenish_on_order\\"/>\\n                    \\t\\t\\t</setting>\\n\\t\\t\\t\\t</block>\\n\\t\\t\\t</xpath>"}	<?xml version="1.0"?>\n<xpath expr="//app[@name='purchase']" position="inside">\n\t\t\t\t<field name="is_installed_sale" invisible="1"/>\n\t\t\t\t<block title="Logistics" invisible="not is_installed_sale" name="request_vendor_setting_container">\n\t\t\t\t\t<setting title="This adds a dropshipping route to apply on products in order to request your vendors to deliver to your customers. A product to dropship will generate a purchase request for quotation once the sales order confirmed. This is a on-demand flow. The requested delivery address will be the customer delivery address and not your warehouse." help="Request your vendors to deliver to your customers" documentation="/applications/inventory_and_mrp/inventory/shipping/operation/dropshipping.html">\n\t\t\t\t\t\t<field name="module_stock_dropshipping"/>\n\t\t\t\t\t</setting>\n\t\t\t\t\t<setting title="This adds a Replenish On Order (MTO) route to apply on products in order to generate on-demand replenishment linked to your sales orders (for example) as soon as they are confirmed, with a direct link. Purchase orders, manufacturing orders, etc. are triggered based on what way to replenish is set on the product (Buy or Manufacture route)." help="Allow Make to Order, or automate PO, when a product is sold and get direct links between documents." documentation="/applications/inventory_and_mrp/inventory/warehouses_storage/replenishment/mto.html" groups="stock.group_stock_manager">\n                        \t\t\t<field name="replenish_on_order"/>\n                    \t\t\t</setting>\n\t\t\t\t</block>\n\t\t\t</xpath>\n\t\t	f	t	2026-11-25 09:29:55.894176	2026-11-25 09:29:55.894176	f	\N	\N	\N	\N	\N	\N	\N	\N	\N	f	f
