ions\\" invisible=\\"1\\"/>\\n                                </group>\\n                                <group>\\n                                    <field name=\\"origin\\" readonly=\\"state in ['cancel', 'done']\\"/>\\n                                    <field name=\\"date_deadline\\"/>\\n                                    <field name=\\"is_delayed\\" invisible=\\"True\\"/>\\n                                    <field name=\\"company_id\\" groups=\\"base.group_multi_company\\" options=\\"{'no_create': True}\\" readonly=\\"state != 'draft'\\" force_save=\\"1\\"/>\\n                                </group>\\n                            </group>\\n                        </page>\\n                    </notebook>\\n                </sheet>\\n                <chatter/>\\n                </form>", "es_ES": "<form string=\\"Órdenes de fabricación\\">\\n                <header>\\n                    <field name=\\"show_lock\\" invisible=\\"1\\"/>\\n                    <field name=\\"show_produce\\" invisible=\\"1\\"/>\\n                    <field name=\\"show_produce_all\\" invisible=\\"1\\"/>\\n                    <button name=\\"button_mark_done\\" invisible=\\"not move_raw_ids or not show_produce\\" string=\\"Producir\\" type=\\"object\\" class=\\"oe_highlight\\" data-hotkey=\\"g\\"/>\\n                    <button name=\\"button_mark_done\\" invisible=\\"not move_raw_ids or not show_produce_all\\" string=\\"Producir todo\\" type=\\"object\\" class=\\"oe_highlight\\" data-hotkey=\\"g\\"/>\\n                    <button name=\\"button_mark_done\\" invisible=\\"move_raw_ids or not show_produce\\" string=\\"Producir\\" type=\\"object\\" class=\\"oe_highlight\\" data-hotkey=\\"g\\" confirm=\\"No hay componentes a consumir. ¿Está seguro de que desea continuar?\\"/>\\n                    <button name=\\"button_mark_done\\" invisible=\\"move_raw_ids or not show_produce_all\\" string=\\"Producir todo\\" type=\\"object\\" class=\\"oe_highlight\\" data-hotkey=\\"g\\" confirm=\