/li>\\n                            <li t-if=\\"not forced_vat\\">\\n                                <t t-if=\\"company.vat\\">\\n                                    <t t-esc=\\"company.country_id.vat_label or 'Tax ID'\\">Tax ID</t>:\\n                                    <span t-esc=\\"company.vat\\">US12345671</span>\\n                                </t>\\n                            </li>\\n                            <li t-else=\\"\\">\\n                                <t t-esc=\\"company.country_id.vat_label or 'Tax ID'\\">Tax ID</t>:\\n                                <span t-esc=\\"forced_vat\\">US12345671</span>\\n                            </li>\\n                        </ul>\\n                    </div>\\n                </div>\\n            </div>\\n        </div>\\n        <t t-set=\\"layout_background_url\\" t-value=\\"'data:image/png;base64,%s' % company.layout_background_image.decode('utf-8') if company.layout_background_image and company.layout_background == 'Custom' else                 '/base/static/img/demo_logo_report.png' if company.layout_background == 'Demo logo' else ''\\"/>\\n        <div t-attf-class=\\"article o_report_layout_boxed o_table_boxed o_company_#{company.id}_layout o_snail_mail {{'o_report_layout_background' if company.layout_background != 'Blank' else ''}}\\" t-attf-style=\\"{{ 'background-image: url(%s);' % layout_background_url if layout_background_url else '' }}\\" t-att-data-oe-model=\\"o and o._name\\" t-att-data-oe-id=\\"o and o.id\\" t-att-data-oe-lang=\\"o and o.env.context.get('lang')\\">\\n            <t t-call=\\"web.address_layout\\"/>\\n            <h2 t-out=\\"layout_document_title\\"/>\\n            <t t-out=\\"0\\"/>\\n        </div>\\n\\n        <div t-attf-class=\\"footer o_company_#{company.id}_layout {{report_type != 'pdf' and 'mt-auto'}}\\">\\n            <div class=\\"o_footer_content\\" t-attf-class=\\"{{'d-flex' if is_html_empty(company.report_header) else 'row' }} o_footer_content border-top pt-2\\">\\n