 class=\\"mt16\\">\\n                            <label for=\\"digest_id\\" class=\\"o_light_label mr8\\"/>\\n                            <field name=\\"digest_id\\" class=\\"oe_inline\\"/>\\n                        </div>\\n                        <div class=\\"mt8\\">\\n                            <button type=\\"action\\" name=\\"210\\" string=\\"Configurar correos electrónicos del resumen\\" icon=\\"oi-arrow-right\\" class=\\"btn-link\\"/>\\n                        </div>\\n                    </div>\\n                </setting>\\n            </xpath>"}	<?xml version="1.0"?>\n<xpath expr="//setting[@id='restrict_template_rendering_setting']" position="before">\n                <setting id="digest" string="Digest Email" help="Add new users as recipient of a periodic email with key metrics" documentation="/applications/general/digest_emails.html" title="New users are automatically added as recipient of the following digest email." name="digest_email_setting_container">\n                    <field name="digest_emails"/>\n                    <div class="content-group" invisible="not digest_emails">\n                        <div class="mt16">\n                            <label for="digest_id" class="o_light_label mr8"/>\n                            <field name="digest_id" class="oe_inline"/>\n                        </div>\n                        <div class="mt8">\n                            <button type="action" name="210" string="Configure Digest Emails" icon="oi-arrow-right" class="btn-link"/>\n                        </div>\n                    </div>\n                </setting>\n            </xpath>\n        	f	t	2026-11-20 12:43:56.916817	2026-11-24 08:36:19.337065	f	\N	\N	\N	\N	\N	\N	\N	\N	\N	f	\N
648	16	\N	1	1	Payment Express Checkout	\N	payment.express_checkout	qweb	payment/views/express_checkout_templates.xml	primary	{"en_US": "<t name=\\"Payment Express Checkout\\" t-name=\\"payment.express_checkout\\">\\n        <!-- Parameters description:\\n            - reference_prefix: The custom prefix to compute the full transaction reference.\\n            - amount: The amount to pay.\\n            - minor_amount: The amount to pay in the minor units of its currency.\\n            - currency: The currency of the payment, as a `res.currency` record.\\n            - providers_sudo: The compatible providers, as a sudoed `payment.provider` recordset.\\n            - merchant_name: The merchant name.\\n            - payment_method_unknown_id: The ID of the \\"Unknown\\" payment method record, to use as\\n                                         the generic express checkout method.\\n            - payment_access_token: The access token used to authenticate the partner. Since this\\n                                    template is loaded in the shopping cart, this parameter is\\n                                    called `payment_access_token` to prevent mixing up with the\\n                                    `access_token` used for abandoned carts.\\n            - shipping_info_required: Whether the shipping information is required or not.\\n            - transaction_route: The route used to create a transaction when the user clicks Pay.\\n            - shipping_address_update_route: The route where available carriers are computed based\\n                                             on the (partial) shipping information available.\\n                                             Optional.\\n            - express_checkout_route: The route where the billing and shipping information are sent.\\n            - landing_route: The route the user is redirected to after the transaction.\\n            - payment_access_token: The access token used to authenticate the partner. Since this\\n                                    template is loaded in the shopping cart, this parameter is\\n                                    called `payment_access_token` to prevent mixing up with the\\n                                    `access_token` used for abandoned carts.\\n        -->\\n        <form name=\\"o_payment_express_checkout_form\\" class=\\"container\\" t-att-data-reference-prefix=\\"reference_prefix\\" t-att-data-amount=\\"amount\\" t-att-data-minor-amount=\\"minor_amount\\" t-att-data-currency-id=\\"currency and currency.id\\" t-att-data-currency-name=\\"currency.name.lower()\\" t-att-data-merchant-name=\\"merchant_name\\" t-att-data-partner-id=\\"partner_id\\" t-att-data-payment-method-unknown-id=\\"payment_method_unknown_id\\" t-att-data-access-token=\\"payment_access_token\\" t-att-data-shipping-info-required=\\"shipping_info_required\\" t-att-data-delivery-amount=\\"delivery_amount\\" t-att-data-transaction-route=\\"transaction_route\\" t-att-data-shipping-address-update-route=\\"shipping_address_update_route\\" t-att-data-express-checkout-route=\\"express_checkout_route\\" t-att-data-landing-route=\\"landing_route\\">\\n            <t t-set=\\"provider_sudo\\" t-value=\\"providers_sudo[:1]\\"/>\\n            <t t-set=\\"express_checkout_form_xml_id\\" t-value=\\"provider_sudo.express_checkout_form_view_id.xml_id\\"/>\\n            <t t-if=\\"express_checkout_form_xml_id\\">\\n                <t t-call=\\"{{express_checkout_form_xml_id}}\\"/>\\n            </t>\\n        </form>\\n    </t>"}	<?xml version="1.0"?>\n<t name="Payment Express Checkout" t-name="payment.express_checkout">\n        <!-- Parameters description:\n            - reference_prefix: The custom prefix to compute the full transaction reference.\n            - amount: The amount to pay.\n            - minor_amount: The amount to pay in the minor units of its currency.\n            - currency: The currency of the payment, as a `res.currency` record.\n            - providers_sudo: The compatible providers, as a sudoed `payment.provider` recordset.\n            - merchant_name: The merchant name.\n            - payment_method_unknown_id: The ID of the "Unknown" payment method record, to use as\n                                         the generic express checkout method.\n            - payment_access_token: The access token used to authenticate the partner. Since this\n                                    template is loaded in the shopping cart, this parameter is\n                                    called `payment_access_token` to prevent mixing up with the\n                                    `access_token` used for abandoned carts.\n            - shipping_info_required: Whether the shipping information is required or not.\n            - transaction_route: The route used to create a transaction when the user clicks Pay.\n            - shipping_address_update_route: The route where available carriers are computed based\n                                             on the (partial) shipping information available.\n                                             Optional.\n            - express_checkout_route: The route where the billing and shipping information are sent.\n            - landing_route: The route the user is redirected to after the transaction.\n            - payment_access_token: The access token used to authenticate the partner. Since this\n                                    template is loaded in the shopping cart, this parameter is\n                                    called `payment_access_token` to prevent mixing up with the\n                                    `access_token` used for abandoned carts.\n        -->\n        <form name="o_payment_express_checkout_form" class="container" t-att-data-reference-prefix="reference_prefix" t-att-data-amount="amount" t-att-data-minor-amount="minor_amount" t-att-data-currency-id="currency and currency.id" t-att-data-currency-name="currency.name.lower()" t-att-data-merchant-name="merchant_name" t-att-data-partner-id="partner_id" t-att-data-payment-method-unknown-id="payment_method_unknown_id" t-att-data-access-token="payment_access_token" t-att-data-shipping-info-required="shipping_info_required" t-att-data-delivery-amount="delivery_amount" t-att-data-transaction-route="transaction_route" t-att-data-shipping-address-update-route="shipping_address_update_route" t-att-data-express-checkout-route="express_checkout_route" t-att-data-landing-route="landing_route">\n            <t t-set="provider_sudo" t-value="providers_sudo[:1]"/>\n            <t t-set="express_checkout_form_xml_id" t-value="provider_sudo.express_checkout_form_view_id.xml_id"/>\n            <t t-if="express_checkout_form_xml_id">\n                <t t-call="{{express_checkout_form_xml_id}}"/>\n            </t>\n        </form>\n    </t>\n\n	f	t	2026-11-20 12:43:57.265472	2026-11-24 08:36:19.337065	f	\N	\N	\N	\N	\N	\N	\N	\N	\N	f	\N
