_form_label\\" readonly=\\"1\\"/>.\\n                </div>\\n                <group string=\\"Información de la empresa\\">\\n                    <label for=\\"account_peppol_contact_email\\" class=\\"text-nowrap\\"/>\\n                    <field name=\\"account_peppol_contact_email\\" nolabel=\\"1\\" required=\\"account_peppol_proxy_state in ('sender', 'smp_registration', 'receiver')\\"/>\\n                </group>\\n                <div invisible=\\"1\\"> <!-- Deprecated -->\\n                    <group string=\\"Reciba sus facturas electrónicas en Odoo\\" invisible=\\"account_peppol_proxy_state != 'sender'\\">\\n                        <div class=\\"text-justify text-muted\\" colspan=\\"2\\">\\n                            Algunos servicios admiten claves de migración. Si es tu caso, introduce tu clave de migración a continuación.\\n                        Si no es así, debes darte de baja de tu proveedor de servicios actual y registrarte con Odoo después.\\n                        </div>\\n                        <field name=\\"account_peppol_migration_key\\"/>\\n                    </group>\\n                    <group string=\\"Autofacturación\\" invisible=\\"account_peppol_proxy_state not in ('sender', 'receiver')\\">\\n                        <field name=\\"peppol_activate_self_billing\\" invisible=\\"account_peppol_proxy_state not in ('sender', 'receiver')\\"/>\\n                        <field name=\\"peppol_self_billing_reception_journal_id\\" invisible=\\"account_peppol_proxy_state != 'receiver'\\"/>\\n                    </group>\\n                </div>\\n                <!-- Note: Deprecated -->\\n                <!-- Disabling services can lead to complicance issues and is not necessary -->\\n                <!-- since all existing services should just work. -->\\n                <group string=\\"Configure sus servicios de Peppol y los formatos permitidos\\" invisible=\\"1\\">\\n                    <div colspan=\\"2\\">\\n                        <fiel