ons_setting_container\\">\\n                            <setting id=\\"work_order\\" string=\\"Órdenes de trabajo\\" help=\\"Procese operaciones en centros de trabajo específicos\\" documentation=\\"/applications/inventory_and_mrp/manufacturing/management/bill_configuration.html#adding-a-routing\\" title=\\"Las operaciones de órdenes de trabajo le permiten crear y administrar las operaciones de fabricación que deben seguirse dentro de sus centros de trabajo para producir un producto. Se adjuntan a listas de materiales que definirán los componentes requeridos.\\">\\n                                <field name=\\"group_mrp_routings\\"/>\\n                                <div id=\\"workorder_settings_workcenters\\" class=\\"content-group\\" invisible=\\"not group_mrp_routings\\">\\n                                    <div class=\\"mt8\\">\\n                                        <div>\\n                                            <button name=\\"491\\" icon=\\"oi-arrow-right\\" type=\\"action\\" string=\\"Centros de trabajo\\" class=\\"btn-link\\"/>\\n                                        </div>\\n                                    </div>\\n                                </div>\\n                                <div id=\\"workorder_settings_dependencies\\" class=\\"row mt-2\\" invisible=\\"not group_mrp_routings\\">\\n                                    <field name=\\"group_mrp_workorder_dependencies\\" class=\\"col flex-grow-0 ml16 mr0 pe-2\\"/>\\n                                    <div class=\\"col ps-0\\">\\n                                        <label for=\\"group_mrp_workorder_dependencies\\"/>\\n                                        <div class=\\"text-muted\\">\\n                                            Establezca el orden en el que se deben procesar las órdenes de trabajo. Active la característica en la pestaña de Varios de cada LdM\\n                                        </div>\\n                                    </div>\\n                      