                    <setting id=\\"mrp_byproduct\\" help=\\"Producir productos residuales (A + B -&gt; C + D)\\" title=\\"Añada subproductos a las listas de materiales. Esto se puede usar para obtener varios productos terminados al mismo tiempo. Sin esta opción, solo puede hacer:  A + B = C. Con ella: A + B = C + D.\\">\\n                                <field name=\\"group_mrp_byproducts\\"/>\\n                            </setting>\\n                            <setting id=\\"mrp_reception_report\\" help=\\"Vea y asigne cantidades de producción a los pedidos de clientes o otras órdenes de fabricación\\">\\n                                <field name=\\"group_mrp_reception_report\\"/>\\n                            </setting>\\n                        </block>\\n                        <block title=\\"Planificación\\">\\n                            <setting id=\\"mrp_mps\\" help=\\"Planificar órdenes de fabricación o pedidos de compra basados en pronósticos\\" documentation=\\"/applications/inventory_and_mrp/manufacturing/management/use_mps.html\\" title=\\"Es útil la utilización de un informe MPS para planificar sus operaciones de reabastecimiento y fabricación si ha tenido tiempo y si se ha producido según el pronóstico de ventas.\\">\\n                                <field name=\\"module_mrp_mps\\" widget=\\"upgrade_boolean\\"/>\\n                            </setting>\\n                        </block>\\n                    </app>\\n                </xpath>"}	<?xml version="1.0"?>\n<xpath expr="//form" position="inside">\n                    <app data-string="Manufacturing" string="Manufacturing" name="mrp" groups="mrp.group_mrp_manager">\n                        <block title="Operations" name="process_operations_setting_container">\n                            <setting id="work_order" string="Work Orders" help="Process operations at specific work centers" documentation="/applications/inventory_and_mrp/manufacturing/management/bill_configuration.html#adding-a-r