1367	16	889	1	1	stock_report_delivery_document_inherit_mrp	\N	mrp.stock_report_delivery_document_inherit_mrp	qweb	mrp/report/report_deliveryslip.xml	extension	{"en_US": "<data inherit_id=\\"stock.report_delivery_document\\">\\n        <!-- needs to be set before so elif directly follows if later on -->\\n        <xpath expr=\\"//t[@name='has_packages']\\" position=\\"before\\">\\n            <!-- get only the top level kits' (i.e. no subkit) move lines for easier mapping later on + we ignore subkit groupings-->\\n            <!-- note that move.name uses top level kit's product.template.display_name value instead of product.template.name -->\\n            <t t-set=\\"has_kits\\" t-value=\\"o.move_line_ids.filtered(lambda l: l.move_id.bom_line_id and l.move_id.bom_line_id.bom_id.type == 'phantom')\\"/>\\n        </xpath>\\n        <xpath expr=\\"//t[@name='no_package_section']\\" position=\\"before\\">\\n            <t t-set=\\"has_kits\\" t-value=\\"o.move_line_ids.filtered(lambda l: l.move_id.bom_line_id and l.move_id.bom_line_id.bom_id.type == 'phantom')\\"/>\\n            <t t-if=\\"has_kits\\">\\n                <!-- print the products not in a package or kit first -->\\n                <t t-set=\\"move_lines\\" t-value=\\"move_lines.filtered(lambda m: not m.move_id.bom_line_id)\\"/>\\n            </t>\\n        </xpath>\\n        <xpath expr=\\"//t[@name='no_package_move_lines']\\" position=\\"inside\\">\\n            <t t-call=\\"mrp.stock_report_delivery_kit_sections\\"/>\\n        </xpath>\\n        <xpath expr=\\"//t[@name='has_packages']\\" position=\\"after\\">\\n            <!-- Additional use case: group by kits when no packages exist and then apply use case 1. (serial/lot numbers used/printed) -->\\n            <t t-elif=\\"has_kits and not packages_count\\">\\n                <t t-call=\\"mrp.stock_report_delivery_kit_sections\\"/>\\n                <t t-call=\\"mrp.stock_report_delivery_no_kit_section\\"/>\\n            </t>\\n        </xpath>\\n    </data>"}	<?xml version="1.0"?>\n<data inherit_id="stock.report_delivery_document">\n        <!-- needs to be set before so elif directly follows if later on -->\n        <xpath expr="//t[@name='has_packages']" position="before">\n            <!-- get only the top level kits' (i.e. no subkit) move lines for easier mapping later on + we ignore subkit groupings-->\n            <!-- note that move.name uses top level kit's product.template.display_name value instead of product.template.name -->\n            <t t-set="has_kits" t-value="o.move_line_ids.filtered(lambda l: l.move_id.bom_line_id and l.move_id.bom_line_id.bom_id.type == 'phantom')"/>\n        </xpath>\n        <xpath expr="//t[@name='no_package_section']" position="before">\n            <t t-set="has_kits" t-value="o.move_line_ids.filtered(lambda l: l.move_id.bom_line_id and l.move_id.bom_line_id.bom_id.type == 'phantom')"/>\n            <t t-if="has_kits">\n                <!-- print the products not in a package or kit first -->\n                <t t-set="move_lines" t-value="move_lines.filtered(lambda m: not m.move_id.bom_line_id)"/>\n            </t>\n        </xpath>\n        <xpath expr="//t[@name='no_package_move_lines']" position="inside">\n            <t t-call="mrp.stock_report_delivery_kit_sections"/>\n        </xpath>\n        <xpath expr="//t[@name='has_packages']" position="after">\n            <!-- Additional use case: group by kits when no packages exist and then apply use case 1. (serial/lot numbers used/printed) -->\n            <t t-elif="has_kits and not packages_count">\n                <t t-call="mrp.stock_report_delivery_kit_sections"/>\n                <t t-call="mrp.stock_report_delivery_no_kit_section"/>\n            </t>\n        </xpath>\n    </data>\n\n    	f	t	2026-11-22 17:49:16.491215	2026-11-24 08:36:19.337065	f	\N	\N	\N	\N	\N	\N	\N	\N	\N	f	\N
