1815	16	1814	1	1	new_page_template_team_0_s_three_columns	\N	website.new_page_template_team_0_s_three_columns	qweb	website/views/new_page_template_templates.xml	primary	{"en_US": "<data inherit_id=\\"website.new_page_template_team_s_three_columns\\" primary=\\"True\\">\\n    <xpath expr=\\"//h2|//h3|//h4|//h5\\" position=\\"replace\\">\\n        <h2 class=\\"card-title h5-fs\\">Tony Fred, CEO</h2>\\n    </xpath>\\n    <xpath expr=\\"(//h2|//h3|//h4|//h5)[2]\\" position=\\"replace\\">\\n        <h2 class=\\"card-title h5-fs\\">Mich Stark, COO</h2>\\n    </xpath>\\n    <xpath expr=\\"(//h2|//h3|//h4|//h5)[3]\\" position=\\"replace\\">\\n        <h2 class=\\"card-title h5-fs\\">Aline Turner, CTO</h2>\\n    </xpath>\\n    <xpath expr=\\"//div[hasclass('card')]//p|//div[hasclass('card-wrapper')]//p\\" position=\\"replace\\">\\n        <p class=\\"card-text\\">Founder and chief visionary, Tony is the driving force behind the company. He loves to keep his hands full by participating in the development of the software, marketing, and customer experience strategies.</p>\\n    </xpath>\\n    <xpath expr=\\"(//div[hasclass('card')])[2]//p|(//div[hasclass('card-wrapper')])[2]//p\\" position=\\"replace\\">\\n        <p class=\\"card-text\\">Mich loves taking on challenges. With his multi-year experience as Commercial Director in the software industry, Mich has helped the company to get where it is today. Mich is among the best minds.</p>\\n    </xpath>\\n    <xpath expr=\\"(//div[hasclass('card')])[3]//p|(//div[hasclass('card-wrapper')])[3]//p\\" position=\\"replace\\">\\n        <p class=\\"card-text\\">Aline is one of the iconic people in life who can say they love what they do. She mentors 100+ in-house developers and looks after the community of thousands of developers.</p>\\n    </xpath>\\n    <xpath expr=\\"//img\\" position=\\"replace\\">\\n        <img alt=\\"\\" src=\\"/web/image/website.s_company_team_image_1\\" class=\\"o_card_img card-img-top\\"/>\\n    </xpath>\\n    <xpath expr=\\"(//img)[2]\\" position=\\"replace\\">\\n        <img alt=\\"\\" src=\\"/web/image/website.s_company_team_image_2\\" class=\\"o_card_img card-img-top\\"/>\\n    </xpath>\\n    <xpath expr=\\"(//img)[3]\\" position=\\"replace\\">\\n        <img alt=\\"\\" src=\\"/web/image/website.s_company_team_image_3\\" class=\\"o_card_img card-img-top\\"/>\\n    </xpath>\\n<xpath expr=\\".\\" position=\\"attributes\\"><attribute name=\\"t-name\\">website.new_page_template_team_0_s_three_columns</attribute></xpath></data>", "es_ES": "<data inherit_id=\\"website.new_page_template_team_s_three_columns\\" primary=\\"True\\">\\n    <xpath expr=\\"//h2|//h3|//h4|//h5\\" position=\\"replace\\">\\n        <h2 class=\\"card-title h5-fs\\">Tony Fred, director ejecutivo</h2>\\n    </xpath>\\n    <xpath expr=\\"(//h2|//h3|//h4|//h5)[2]\\" position=\\"replace\\">\\n        <h2 class=\\"card-title h5-fs\\">Mich Stark, director de operaciones</h2>\\n    </xpath>\\n    <xpath expr=\\"(//h2|//h3|//h4|//h5)[3]\\" position=\\"replace\\">\\n        <h2 class=\\"card-title h5-fs\\">Aline Turner, CTO</h2>\\n    </xpath>\\n    <xpath expr=\\"//div[hasclass('card')]//p|//div[hasclass('card-wrapper')]//p\\" position=\\"replace\\">\\n        <p class=\\"card-text\\">Tony, fundador y visionario principal, es la fuerza que mueve a la empresa. Le encanta participar en el desarrollo de software, en marketing y en estrategias de experiencias para los usuarios.</p>\\n    </xpath>\\n    <xpath expr=\\"(//div[hasclass('card')])[2]//p|(//div[hasclass('card-wrapper')])[2]//p\\" position=\\"replace\\">\\n        <p class=\\"card-text\\">Mich cuenta con varios años de experiencia como director comercial en el sector informático. Le encantan los desafíos y ha ayudado a la empresa a llegar hasta donde está hoy. Mich está entre las mejores mentes.</p>\\n    </xpath>\\n    <xpath expr=\\"(//div[hasclass('card')])[3]//p|(//div[hasclass('card-wrapper')])[3]//p\\" position=\\"replace\\">\\n        <p class=\\"card-text\\">Aline es una de las personas icónicas en la vida que puede decir que les encanta lo que hacen. Ella es mentora de más de 100 desarrolladores internos y se ocupa de la comunidad de miles de desarrolladores.</p>\\n    </xpath>\\n    <xpath expr=\\"//img\\" position=\\"replace\\">\\n        <img alt=\\"\\" src=\\"/web/image/website.s_company_team_image_1\\" class=\\"o_card_img card-img-top\\"/>\\n    </xpath>\\n    <xpath expr=\\"(//img)[2]\\" position=\\"replace\\">\\n        <img alt=\\"\\" src=\\"/web/image/website.s_company_team_image_2\\" class=\\"o_card_img card-img-top\\"/>\\n    </xpath>\\n    <xpath expr=\\"(//img)[3]\\" position=\\"replace\\">\\n        <img alt=\\"\\" src=\\"/web/image/website.s_company_team_image_3\\" class=\\"o_card_img card-img-top\\"/>\\n    </xpath>\\n<xpath expr=\\".\\" position=\\"attributes\\"><attribute name=\\"t-name\\">website.new_page_template_team_0_s_three_columns</attribute></xpath></data>"}	<?xml version="1.0"?>\n<data inherit_id="website.new_page_template_team_s_three_columns" primary="True">\n    <xpath expr="//h2|//h3|//h4|//h5" position="replace">\n        <h2 class="card-title h5-fs">Tony Fred, CEO</h2>\n    </xpath>\n    <xpath expr="(//h2|//h3|//h4|//h5)[2]" position="replace">\n        <h2 class="card-title h5-fs">Mich Stark, COO</h2>\n    </xpath>\n    <xpath expr="(//h2|//h3|//h4|//h5)[3]" position="replace">\n        <h2 class="card-title h5-fs">Aline Turner, CTO</h2>\n    </xpath>\n    <xpath expr="//div[hasclass('card')]//p|//div[hasclass('card-wrapper')]//p" position="replace">\n        <p class="card-text">Founder and chief visionary, Tony is the driving force behind the company. He loves to keep his hands full by participating in the development of the software, marketing, and customer experience strategies.</p>\n    </xpath>\n    <xpath expr="(//div[hasclass('card')])[2]//p|(//div[hasclass('card-wrapper')])[2]//p" position="replace">\n        <p class="card-text">Mich loves taking on challenges. With his multi-year experience as Commercial Director in the software industry, Mich has helped the company to get where it is today. Mich is among the best minds.</p>\n    </xpath>\n    <xpath expr="(//div[hasclass('card')])[3]//p|(//div[hasclass('card-wrapper')])[3]//p" position="replace">\n        <p class="card-text">Aline is one of the iconic people in life who can say they love what they do. She mentors 100+ in-house developers and looks after the community of thousands of developers.</p>\n    </xpath>\n    <xpath expr="//img" position="replace">\n        <img alt="" src="/web/image/website.s_company_team_image_1" class="o_card_img card-img-top"/>\n    </xpath>\n    <xpath expr="(//img)[2]" position="replace">\n        <img alt="" src="/web/image/website.s_company_team_image_2" class="o_card_img card-img-top"/>\n    </xpath>\n    <xpath expr="(//img)[3]" position="replace">\n        <img alt="" src="/web/image/website.s_company_team_image_3" class="o_card_img card-img-top"/>\n    </xpath>\n<xpath expr="." position="attributes"><attribute name="t-name">website.new_page_template_team_0_s_three_columns</attribute></xpath></data>\n\n	f	t	2026-11-24 08:36:19.337065	2026-11-24 08:36:19.337065	f	\N	\N	\N	\N	\N	\N	\N	\N	\N	f	f
1824	16	1823	1	1	new_page_template_landing_2_s_call_to_action	\N	website.new_page_template_landing_2_s_call_to_action	qweb	website/views/new_page_template_templates.xml	primary	{"en_US": "<data inherit_id=\\"new_page_template_landing_s_call_to_action\\" primary=\\"True\\">\\n    <xpath expr=\\"//h2|//h3|//h4\\" position=\\"replace\\">\\n        <h3>Ready to Embrace Your Fitness Journey?</h3>\\n    </xpath>\\n    <xpath expr=\\"//p\\" position=\\"replace\\">\\n        <p class=\\"lead\\">Contact us today to embark on your path to a healthier, more vibrant you. Your fitness journey begins here.</p>\\n    </xpath>\\n<xpath expr=\\".\\" position=\\"attributes\\"><attribute name=\\"t-name\\">website.new_page_template_landing_2_s_call_to_action</attribute></xpath></data>", "es_ES": "<data inherit_id=\\"new_page_template_landing_s_call_to_action\\" primary=\\"True\\">\\n    <xpath expr=\\"//h2|//h3|//h4\\" position=\\"replace\\">\\n        <h3>¿Listo para iniciar su viaje hacia el bienestar físico?</h3>\\n    </xpath>\\n    <xpath expr=\\"//p\\" position=\\"replace\\">\\n        <p class=\\"lead\\">Póngase en contacto con nosotros ahora mismo para iniciar su viaje hacia una vida más sana y alegre. Su camino hacia un buen estado físico comienza aquí.</p>\\n    </xpath>\\n<xpath expr=\\".\\" position=\\"attributes\\"><attribute name=\\"t-name\\">website.new_page_template_landing_2_s_call_to_action</attribute></xpath></data>"}	<?xml version="1.0"?>\n<data inherit_id="new_page_template_landing_s_call_to_action" primary="True">\n    <xpath expr="//h2|//h3|//h4" position="replace">\n        <h3>Ready to Embrace Your Fitness Journey?</h3>\n    </xpath>\n    <xpath expr="//p" position="replace">\n        <p class="lead">Contact us today to embark on your path to a healthier, more vibrant you. Your fitness journey begins here.</p>\n    </xpath>\n<xpath expr="." position="attributes"><attribute name="t-name">website.new_page_template_landing_2_s_call_to_action</attribute></xpath></data>\n\n	f	t	2026-11-24 08:36:19.337065	2026-11-24 08:36:19.337065	f	\N	\N	\N	\N	\N	\N	\N	\N	\N	f	f
1808	16	1807	1	1	new_page_template_about_s_three_columns	\N	website.new_page_template_about_s_three_columns	qweb	website/views/new_page_template_templates.xml	primary	{"en_US": "<data inherit_id=\\"website.new_page_template_s_three_columns\\" primary=\\"True\\">\\n    <xpath expr=\\"//h2|//h3|//h4|//h5\\" position=\\"replace\\">\\n        <h2 class=\\"card-title h5-fs\\">Our Story</h2>\\n    </xpath>\\n    <xpath expr=\\"(//h2|//h3|//h4|//h5)[2]\\" position=\\"replace\\">\\n        <h2 class=\\"card-title h5-fs\\">Our Mission</h2>\\n    </xpath>\\n    <xpath expr=\\"(//h2|//h3|//h4|//h5)[3]\\" position=\\"replace\\">\\n        <h2 class=\\"card-title h5-fs\\">Our Values</h2>\\n    </xpath>\\n    <xpath expr=\\"//p\\" position=\\"replace\\">\\n        <p class=\\"card-text\\">Step into our past and witness the transformation of a simple idea into an innovative force. Our journey, born in a garage, reflects the power of passion and hard work.</p>\\n    </xpath>\\n    <xpath expr=\\"(//p)[2]\\" position=\\"replace\\">\\n        <p class=\\"card-text\\">Our mission is to create transformative experiences and foster growth, driven by a relentless pursuit of innovation and a commitment to exceeding expectations.</p>\\n    </xpath>\\n    <xpath expr=\\"(//p)[3]\\" position=\\"replace\\">\\n        <p class=\\"card-text\\">Our values shape our culture, influence our decisions, and guide us in providing exceptional service. They reflect our dedication to integrity, collaboration, and client satisfaction.</p>\\n    </xpath>\\n<xpath expr=\\".\\" position=\\"attributes\\"><attribute name=\\"t-name\\">website.new_page_template_about_s_three_columns</attribute></xpath></data>", "es_ES": "<data inherit_id=\\"website.new_page_template_s_three_columns\\" primary=\\"True\\">\\n    <xpath expr=\\"//h2|//h3|//h4|//h5\\" position=\\"replace\\">\\n        <h2 class=\\"card-title h5-fs\\">Nuestra historia</h2>\\n    </xpath>\\n    <xpath expr=\\"(//h2|//h3|//h4|//h5)[2]\\" position=\\"replace\\">\\n        <h2 class=\\"card-title h5-fs\\">Nuestra misión</h2>\\n    </xpath>\\n    <xpath expr=\\"(//h2|//h3|//h4|//h5)[3]\\" position=\\"replace\\">\\n        <h2 class=\\"card-title h5-fs\\">Nuestros valores</h2>\\n    </xpath>\\n    <xpath expr=\\"//p\\" position=\\"replace\\">\\n        <p class=\\"card-text\\">Sumérjase en nuestro pasado y sea testigo de la transformación de una simple idea en una fuerza innovadora. Nuestro viaje comenzó en un garaje, lo que refleja el poder de la pasión y el trabajo duro.</p>\\n    </xpath>\\n    <xpath expr=\\"(//p)[2]\\" position=\\"replace\\">\\n        <p class=\\"card-text\\">Nuestra misión es crear experiencias transformadoras y fomentar el crecimiento, gracias a una búsqueda constante de innovación y al compromiso de superar las expectativas.</p>\\n    </xpath>\\n    <xpath expr=\\"(//p)[3]\\" position=\\"replace\\">\\n        <p class=\\"card-text\\">Nuestros valores conforman nuestra cultura, influyen en nuestras decisiones y nos guían para ofrecer un servicio excepcional. Reflejan nuestra dedicación a la integridad, la colaboración y la satisfacción del cliente.</p>\\n    </xpath>\\n<xpath expr=\\".\\" position=\\"attributes\\"><attribute name=\\"t-name\\">website.new_page_template_about_s_three_columns</attribute></xpath></data>"}	<?xml version="1.0"?>\n<data inherit_id="website.new_page_template_s_three_columns" primary="True">\n    <xpath expr="//h2|//h3|//h4|//h5" position="replace">\n        <h2 class="card-title h5-fs">Our Story</h2>\n    </xpath>\n    <xpath expr="(//h2|//h3|//h4|//h5)[2]" position="replace">\n        <h2 class="card-title h5-fs">Our Mission</h2>\n    </xpath>\n    <xpath expr="(//h2|//h3|//h4|//h5)[3]" position="replace">\n        <h2 class="card-title h5-fs">Our Values</h2>\n    </xpath>\n    <xpath expr="//p" position="replace">\n        <p class="card-text">Step into our past and witness the transformation of a simple idea into an innovative force. Our journey, born in a garage, reflects the power of passion and hard work.</p>\n    </xpath>\n    <xpath expr="(//p)[2]" position="replace">\n        <p class="card-text">Our mission is to create transformative experiences and foster growth, driven by a relentless pursuit of innovation and a commitment to exceeding expectations.</p>\n    </xpath>\n    <xpath expr="(//p)[3]" position="replace">\n        <p class="card-text">Our values shape our culture, influence our decisions, and guide us in providing exceptional service. They reflect our dedication to integrity, collaboration, and client satisfaction.</p>\n    </xpath>\n<xpath expr="." position="attributes"><attribute name="t-name">website.new_page_template_about_s_three_columns</attribute></xpath></data>\n\n	f	t	2026-11-24 08:36:19.337065	2026-11-24 08:36:19.337065	f	\N	\N	\N	\N	\N	\N	\N	\N	\N	f	f
