|//h3|//h4|//h5)[2]\\" position=\\"replace\\">\\n        <h2 class=\\"card-title h5-fs\\">Entrenamiento de fuerza: </h2>\\n    </xpath>\\n    <xpath expr=\\"(//h2|//h3|//h4|//h5)[3]\\" position=\\"replace\\">\\n        <h2 class=\\"card-title h5-fs\\">Transformación de la pérdida de peso</h2>\\n    </xpath>\\n    <xpath expr=\\"//p\\" position=\\"replace\\">\\n        <p class=\\"card-text\\">Nuestro entrenamiento combina planes personalizados de entrenamiento físico con prácticas de atención plena para garantizar la armonía del cuerpo y de la mente.</p>\\n    </xpath>\\n    <xpath expr=\\"(//p)[2]\\" position=\\"replace\\">\\n        <p class=\\"card-text\\">Este programa de entrenamiento ofrece entrenamientos especializados centrados en la fuerza, orientación nutricional y asesoramiento especializado. Mejore su forma física y consiga logros que nunca creyó posibles.</p>\\n    </xpath>\\n    <xpath expr=\\"(//p)[3]\\" position=\\"replace\\">\\n        <p class=\\"card-text\\">Gracias a los planes de entrenamiento y nutrición personalizada, así como a un apoyo constante, podrá deshacerse de los kilos de más y crear hábitos saludables duraderos.</p>\\n    </xpath>\\n<xpath expr=\\".\\" position=\\"attributes\\"><attribute name=\\"t-name\\">website.new_page_template_services_0_s_three_columns</attribute></xpath></data>"}	<?xml version="1.0"?>\n<data inherit_id="website.new_page_template_services_s_three_columns" primary="True">\n    <xpath expr="//h2|//h3|//h4|//h5" position="replace">\n        <h2 class="card-title h5-fs">Wellness Coaching</h2>\n    </xpath>\n    <xpath expr="(//h2|//h3|//h4|//h5)[2]" position="replace">\n        <h2 class="card-title h5-fs">Strength Training: </h2>\n    </xpath>\n    <xpath expr="(//h2|//h3|//h4|//h5)[3]" position="replace">\n        <h2 class="card-title h5-fs">Weight Loss Transformation</h2>\n    </xpath>\n    <xpath expr="//p" position="replace">\n        <p class="card-text">Our Coaching combines personalized fitness plans with mindfulness practices, ensuring you achieve harmony in your body and peace in your mind.</p>\n    </xpath>\n    <xpath expr="(//p)[2]" position="replace">\n        <p class="card-text">This coaching program offers specialized strength-focused workouts, nutrition guidance, and expert coaching. Elevate your fitness level and achieve feats you never thought possible.</p>\n    </xpath>\n    <xpath expr="(//p)[3]" position="replace">\n        <p class="card-text">With personalized fitness plans, tailored nutrition guidance, and consistent support, you'll shed unwanted pounds while building healthy habits that last.</p>\n    </xpath>\n<xpath expr="." position="attributes"><attribute name="t-name">website.new_page_template_services_0_s_three_columns</attribute></xpath></data>\n\n	f	t	2026-11-24 08:36:19.337065	2026-11-24 08:36:19.337065	f	\N	\N	\N	\N	\N	\N	\N	\N	\N	f	f
