1832	16	1831	1	1	new_page_template_team_s_media_list	\N	website.new_page_template_team_s_media_list	qweb	website/views/new_page_template_templates.xml	primary	{"en_US": "<data inherit_id=\\"website.new_page_template_s_media_list\\" primary=\\"True\\">\\n    <xpath expr=\\"//h3|//h4|//h5\\" position=\\"replace\\">\\n        <h3 class=\\"card-title\\">Tony Fred, CEO</h3>\\n    </xpath>\\n    <xpath expr=\\"(//h3|//h4|//h5)[last()]\\" position=\\"replace\\">\\n        <h3 class=\\"card-title\\">Aline Turner, CTO</h3>\\n    </xpath>\\n    <xpath expr=\\"(//h3|//h4|//h5)[2]\\" position=\\"replace\\">\\n        <h3 class=\\"card-title\\">Mich Stark, COO</h3>\\n    </xpath>\\n    <xpath expr=\\"//p\\" position=\\"replace\\">\\n        <p class=\\"card-text\\">Founder, Tony is the driving force behind the company. He loves to keep his hands full by participating in the development of the software, marketing, and UX strategies.</p>\\n    </xpath>\\n    <xpath expr=\\"(//p)[last()]\\" position=\\"replace\\">\\n        <p class=\\"card-text\\">Aline is one of the iconic people in life who can say they love what they do. She mentors 100+ in-house developers and looks after the community of thousands of developers.</p>\\n    </xpath>\\n    <xpath expr=\\"(//p)[2]\\" position=\\"replace\\">\\n        <p class=\\"card-text\\">Mich loves taking on challenges. With his multi-year experience as Commercial Director in the software industry, Mich has helped the company to get where it is today. Mich is among the best minds.</p>\\n    </xpath>\\n    <xpath expr=\\"//img\\" position=\\"replace\\">\\n        <img alt=\\"\\" src=\\"/web/image/website.s_company_team_image_1\\" class=\\"s_media_list_img h-100 w-100\\"/>\\n    </xpath>\\n    <xpath expr=\\"(//img)[last()]\\" position=\\"replace\\">\\n        <img alt=\\"\\" src=\\"/web/image/website.s_company_team_image_3\\" class=\\"s_media_list_img h-100 w-100\\"/>\\n    </xpath>\\n    <xpath expr=\\"(//img)[2]\\" position=\\"replace\\">\\n        <img alt=\\"\\" src=\\"/web/image/website.s_company_team_image_2\\" class=\\"s_media_list_img h-100 w-100\\"/>\\n    </xpath>\\n<xpath expr=\\".\\" position=\\"attributes\\"><attribute name=\\"t-name\\">website.new_page_template_team_s_media_list</attribute></xpath></data>", "es_ES": "<data inherit_id=\\"website.new_page_template_s_media_list\\" primary=\\"True\\">\\n    <xpath expr=\\"//h3|//h4|//h5\\" position=\\"replace\\">\\n        <h3 class=\\"card-title\\">Tony Fred, director ejecutivo</h3>\\n    </xpath>\\n    <xpath expr=\\"(//h3|//h4|//h5)[last()]\\" position=\\"replace\\">\\n        <h3 class=\\"card-title\\">Aline Turner, CTO</h3>\\n    </xpath>\\n    <xpath expr=\\"(//h3|//h4|//h5)[2]\\" position=\\"replace\\">\\n        <h3 class=\\"card-title\\">Mich Stark, director de operaciones</h3>\\n    </xpath>\\n    <xpath expr=\\"//p\\" position=\\"replace\\">\\n        <p class=\\"card-text\\">Tony, fundador y visionario principal, es la fuerza que mueve a la empresa. Le encanta participar en el desarrollo de software, en marketing y en estrategias de experiencias para los usuarios.</p>\\n    </xpath>\\n    <xpath expr=\\"(//p)[last()]\\" position=\\"replace\\">\\n        <p class=\\"card-text\\">Aline es una de las personas icónicas en la vida que puede decir que les encanta lo que hacen. Ella es mentora de más de 100 desarrolladores internos y se ocupa de la comunidad de miles de desarrolladores.</p>\\n    </xpath>\\n    <xpath expr=\\"(//p)[2]\\" position=\\"replace\\">\\n        <p class=\\"card-text\\">Mich cuenta con varios años de experiencia como director comercial en el sector informático. Le encantan los desafíos y ha ayudado a la empresa a llegar hasta donde está hoy. Mich está entre las mejores mentes.</p>\\n    </xpath>\\n    <xpath expr=\\"//img\\" position=\\"replace\\">\\n        <img alt=\\"\\" src=\\"/web/image/website.s_company_team_image_1\\" class=\\"s_media_list_img h-100 w-100\\"/>\\n    </xpath>\\n    <xpath expr=\\"(//img)[last()]\\" position=\\"replace\\">\\n        <img alt=\\"\\" src=\\"/web/image/website.s_company_team_image_3\\" class=\\"s_media_list_img h-100 w-100\\"/>\\n    </xpath>\\n    <xpath expr=\\"(//img)[2]\\" position=\\"replace\\">\\n        <img alt=\\"\\" src=\\"/web/image/website.s_company_team_image_2\\" class=\\"s_media_list_img h-100 w-100\\"/>\\n    </xpath>\\n<xpath expr=\\".\\" position=\\"attributes\\"><attribute name=\\"t-name\\">website.new_page_template_team_s_media_list</attribute></xpath></data>"}	<?xml version="1.0"?>\n<data inherit_id="website.new_page_template_s_media_list" primary="True">\n    <xpath expr="//h3|//h4|//h5" position="replace">\n        <h3 class="card-title">Tony Fred, CEO</h3>\n    </xpath>\n    <xpath expr="(//h3|//h4|//h5)[last()]" position="replace">\n        <h3 class="card-title">Aline Turner, CTO</h3>\n    </xpath>\n    <xpath expr="(//h3|//h4|//h5)[2]" position="replace">\n        <h3 class="card-title">Mich Stark, COO</h3>\n    </xpath>\n    <xpath expr="//p" position="replace">\n        <p class="card-text">Founder, Tony is the driving force behind the company. He loves to keep his hands full by participating in the development of the software, marketing, and UX strategies.</p>\n    </xpath>\n    <xpath expr="(//p)[last()]" position="replace">\n        <p class="card-text">Aline is one of the iconic people in life who can say they love what they do. She mentors 100+ in-house developers and looks after the community of thousands of developers.</p>\n    </xpath>\n    <xpath expr="(//p)[2]" position="replace">\n        <p class="card-text">Mich loves taking on challenges. With his multi-year experience as Commercial Director in the software industry, Mich has helped the company to get where it is today. Mich is among the best minds.</p>\n    </xpath>\n    <xpath expr="//img" position="replace">\n        <img alt="" src="/web/image/website.s_company_team_image_1" class="s_media_list_img h-100 w-100"/>\n    </xpath>\n    <xpath expr