id.\\n        </t>\\n        <t t-else=\\"\\">\\n            Please remit payment at your earliest convenience.\\n            <t t-if=\\"object.payment_reference\\">\\n                <br/><br/>\\n                Please use the following communication for your payment: <strong t-out=\\"object.payment_reference or ''\\">INV/2021/05/0005</strong>\\n                <t t-if=\\"object.partner_bank_id\\">\\n                    on the account <strong t-out=\\"object.partner_bank_id.acc_number\\"/>\\n                </t>\\n                .\\n            </t>\\n        </t>\\n        <t t-if=\\"hasattr(object, 'timesheet_count') and object.timesheet_count\\">\\n            <br/><br/>\\n            PS: you can review your timesheets <a t-att-href=\\"'/my/timesheets?search_in=invoice&amp;search=%s' % object.name\\">from the portal.</a>\\n        </t>\\n        <br/><br/>\\n        Do not hesitate to contact us if you have any questions.\\n        <t t-if=\\"not is_html_empty(object.invoice_user_id.signature)\\" data-o-mail-quote-container=\\"1\\">\\n            <br/><br/>\\n            <div data-o-mail-quote=\\"1\\">--<br data-o-mail-quote=\\"1\\"/><t t-out=\\"object.invoice_user_id.signature or ''\\" data-o-mail-quote=\\"1\\">Mitchell Admin</t></div>\\n        </t>\\n    </p>\\n</div>\\n            ", "es_ES": "<div style=\\"margin: 0px; padding: 0px;\\">\\n    <p style=\\"margin: 0px; padding: 0px; font-size: 13px;\\">\\n        Estimado\\n        <t t-if=\\"object.partner_id.parent_id\\">\\n            <t t-if=\\"object.partner_id.name\\">\\n                <t t-out=\\"object.partner_id.name\\">Brandon Freeman</t> (<t t-out=\\"object.partner_id.parent_id.name or ''\\">Azure Interior</t>):\\n            </t>\\n            <t t-else=\\"\\">\\n                <t t-out=\\"object.partner_id.parent_id.name or ''\\">Azure Interior</t>,\\n            </t>\\n        </t>\\n        <t t-else=\\"\\">\\n            <t t-out=\\"object.partner_id.name or ''\\">Brandon Freeman</t>,\\n        </t>\\n        <br/><br/>\\n        Aquí encontrará su\\n        <t t-if=\\"object.name\\">\\n            factura <span style=\\"font-weight:bold;\\" t-out=\\"object.name or ''\\">INV/2021/05/0005</span>\\n        </t>\\n        <t t-else=\\"\\">\\n            factura\\n        </t>\\n        <t t-if=\\"object.invoice_origin\\">\\n            (con referencia: <t t-out=\\"object.invoice_origin or ''\\">SUB003</t>)\\n        </t>\\n        por un importe de <span style=\\"font-weight:bold;\\" t-out=\\"format_amount(object.amount_total, object.currency_id) or ''\\">143.750,00 €</span>\\n        de <t t-out=\\"object.company_id.name or ''\\">SuEmpresa</t>.\\n        <t t-if=\\"object.payment_state in ('paid', 'in_payment')\\">\\n            Esta factura ya está pagada.\\n        </t>\\n        <t t-else=\\"\\">\\n            Efectúe el pago lo antes posible.\\n            <t t-if=\\"object.payment_reference\\">\\n                <br/><br/>\\n                Por favor, utilice la siguiente referencia para efectuar el pago: <strong t-out=\\"object.payment_reference or ''\\">INV/2021/05/0005</strong>\\n                <t t-if=\\"object.partner_bank_id\\">\\n                    en la cuenta <strong t-out=\\"object.partner_bank_id.acc_number\\"/>\\n                </t>\\n                .\\n            </t>\\n        </t>\\n        <t t-if=\\"hasattr(object, 'timesheet_count') and object.timesheet_count\\">\\n            <br/><br/>\\n            Recuerde que puede revisar sus partes de horas <a t-att-href=\\"'/my/timesheets?search_in=invoice&amp;search=%s' % object.name\\">desde el portal.</a>\\n        </t>\\n        <br/><br/>\\n        Contacte con nosotros si tiene alguna pregunta.\\n        <t t-if=\\"not is_html_empty(object.invoice_user_id.signature)\\" data-o-mail-quote-container=\\"1\\">\\n            <br/><br/>\\n            <div data-o-mail-quote=\\"1\\">--<br data-o-mail-quote=\\"1\\"/><t t-out=\\"object.invoice_user_id.signature or ''\\" data-o-mail-quote=\