2	16	1	1	s_company_team	theme_anelusia.s_company_team	qweb	\N	theme_anelusia/views/snippets/s_company_team.xml	ir.ui.view,1591	{"en_US": "<data inherit_id=\\"website.s_company_team\\">\\n    <!-- Section -->\\n    <xpath expr=\\"section\\" position=\\"attributes\\">\\n        <attribute name=\\"class\\" add=\\"pt64 pb64\\" remove=\\"pt48 pb48\\" separator=\\" \\"/>\\n    </xpath>\\n\\n    <!-- Team #01 -->\\n    <xpath expr=\\"//div[hasclass('col-lg-6')]//img\\" position=\\"attributes\\">\\n        <attribute name=\\"class\\" remove=\\"rounded-circle\\" separator=\\" \\"/>\\n    </xpath>\\n    <!-- Team #01 - Title -->\\n    <xpath expr=\\"//div[hasclass('col-lg-6')]//h3\\" position=\\"replace\\" mode=\\"inner\\">\\n        <font style=\\"background-image: linear-gradient(135deg, var(--o-color-1) 0%, var(--o-color-5) 100%);\\" class=\\"text-gradient\\">Tony Fred</font>\\n    </xpath>\\n    <!-- Team #01 - Work Description -->\\n    <xpath expr=\\"//div[hasclass('col-lg-6')]//p\\" position=\\"replace\\" mode=\\"inner\\">\\n        Editor-in-chief\\n    </xpath>\\n    <!-- Team #01 - Paragraph -->\\n    <xpath expr=\\"//div[hasclass('col-lg-6')]//p[2]\\" position=\\"replace\\" mode=\\"inner\\">\\n        Founder and chief visionary, Tony is the driving force behind the company. He loves to keep his hands full by participating in the development of the magazine and does not hesitate to carry out field surveys.\\n    </xpath>\\n    <!-- Team #01 - Img -->\\n    <xpath expr=\\"//img\\" position=\\"attributes\\">\\n        <attribute name=\\"src\\">/html_editor/image_shape/website.s_company_team_image_1/html_builder/geometric/geo_square_1.svg</attribute>\\n        <attribute name=\\"data-shape\\">html_builder/geometric/geo_square_1</attribute>\\n        <attribute name=\\"data-format-mimetype\\">image/webp</attribute>\\n        <attribute name=\\"data-file-name\\">uiface_1.svg</attribute>\\n        <attribute name=\\"data-shape-colors\\">;;;;</attribute>\\n    </xpath>\\n\\n    <!-- Team #02 -->\\n    <xpath expr=\\"//div[hasclass('col-lg-6')][2]//img\\" position=\\"attributes\\">\\n        <attribute name=\\"class\\" remove=\\"rounded-circle\\" separator=\\" \\"/>\\n    </xpath>\\n    <!-- Team #02 - Title -->\\n    <xpath expr=\\"//div[hasclass('col-lg-6')][2]//h3\\" position=\\"replace\\" mode=\\"inner\\">\\n        <font style=\\"background-image: linear-gradient(135deg, var(--o-color-1) 0%, var(--o-color-5) 100%);\\" class=\\"text-gradient\\">Mich Stark</font>\\n        <br/>\\n    </xpath>\\n    <!-- Team #02 - Work Description -->\\n    <xpath expr=\\"//div[hasclass('col-lg-6')][2]//p\\" position=\\"replace\\" mode=\\"inner\\">\\n        Sports Reporter\\n    </xpath>\\n    <!-- Team #02 - Paragraph -->\\n    <xpath expr=\\"//div[hasclass('col-lg-6')][2]//p[2]\\" position=\\"replace\\" mode=\\"inner\\">\\n        Mich loves taking on challenges. With his multi-year experience as a journalist, he wanted to join a team that puts people at the center of the stories.\\n    </xpath>\\n    <!-- Team #02 - Img -->\\n    <xpath expr=\\"(//img)[2]\\" position=\\"attributes\\">\\n        <attribute name=\\"src\\">/html_editor/image_shape/website.s_company_team_image_2/html_builder/geometric/geo_square_2.svg</attribute>\\n        <attribute name=\\"data-shape\\">html_builder/geometric/geo_square_2</attribute>\\n        <attribute name=\\"data-format-mimetype\\">image/webp</attribute>\\n        <attribute name=\\"data-file-name\\">uiface_2.svg</attribute>\\n        <attribute name=\\"data-shape-colors\\">;;;;</attribute>\\n    </xpath>\\n\\n    <!-- Team #03 -->\\n    <xpath expr=\\"//div[hasclass('col-lg-6')][3]//img\\" position=\\"attributes\\">\\n        <attribute name=\\"class\\" remove=\\"rounded-circle\\" separator=\\" \\"/>\\n    </xpath>\\n    <!-- Team #03 - Title -->\\n    <xpath expr=\\"//div[hasclass('col-lg-6')][3]//h3\\" position=\\"replace\\" mode=\\"inner\\">\\n        <font style=\\"background-image: linear-gradient(135deg, var(--o-color-2) 0%, var(--o-color-5) 100%);\\" class=\\"text-gradient\\">Aline Turner</font>\\n    </xpath>\\n    <!-- Team #03 - Work Description -->\\n    <xpath expr=\\"//div[hasclass('col-lg-6')][3]//p\\" position=\\"replace\\" mode=\\"inner\\">\\n        Photograph\\n    </xpath>\\n    <!-- Team #03 - Paragraph -->\\n    <xpath expr=\\"//div[hasclass('col-lg-6')][3]//p[2]\\" position=\\"replace\\" mode=\\"inner\\">\\n        Aline is one of the iconic people in life who can say they love what they do. She likes to capture the moment from another point of view, another perspective.\\n    </xpath>\\n    <!-- Team #03 - Img -->\\n    <xpath expr=\\"(//img)[3]\\" position=\\"attributes\\">\\n        <attribute name=\\"src\\">/html_editor/image_shape/website.s_company_team_image_3/html_builder/geometric/geo_square_3.svg</attribute>\\n        <attribute name=\\"data-shape\\">html_builder/geometric/geo_square_3</attribute>\\n        <attribute name=\\"data-format-mimetype\\">image/webp</attribute>\\n        <attribute name=\\"data-file-name\\">uiface_3.svg</attribute>\\n        <attribute name=\\"data-shape-colors\\">;;;;</attribute>\\n    </xpath>\\n\\n    <!-- Team #04 -->\\n    <xpath expr=\\"//div[hasclass('col-lg-6')][4]//img\\" position=\\"attributes\\">\\n        <attribute name=\\"class\\" remove=\\"rounded-circle\\" separator=\\" \\"/>\\n    </xpath>\\n    <!-- Team #04 - Title -->\\n    <xpath expr=\\"//div[hasclass('col-lg-6')][4]//h3\\" position=\\"replace\\" mode=\\"inner\\">\\n        <font style=\\"background-image: linear-gradient(135deg, var(--o-color-2) 0%, var(--o-color-5) 100%);\\" class=\\"text-gradient\\">Iris Joe</font>\\n    </xpath>\\n    <!-- Team #04 - Work Description -->\\n    <xpath expr=\\"//div[hasclass('col-lg-6')][3]//p\\" position=\\"replace\\" mode=\\"inner\\">\\n        Political Reporter\\n    </xpath>\\n    <!-- Team #04 - Paragraph -->\\n    <xpath expr=\\"//div[hasclass('col-lg-6')][4]//p[2]\\" position=\\"replace\\" mode=\\"inner\\">\\n        Iris, with her international experience, helps us easily understand global politics. She is determined to drive success and delivers her professional acumen to bring the magazine to the next level.\\n    </xpath>\\n    <!-- Team #04 - Img -->\\n    <xpath expr=\\"(//img)[4]\\" position=\\"attributes\\">\\n        <attribute name=\\"src\\">/html_editor/image_shape/website.s_company_team_image_4/html_builder/geometric/geo_square_1.svg</attribute>\\n        <attribute name=\\"data-shape\\">html_builder/geometric/geo_square_1</attribute>\\n        <attribute name=\\"data-format-mimetype\\">image/webp</attribute>\\n        <attribute name=\\"data-file-name\\">uiface_4.svg</attribute>\\n        <attribute name=\\"data-shape-colors\\">;;;;</attribute>\\n    </xpath>\\n</data>", "es_ES": "<data inherit_id=\\"website.s_company_team\\">\\n    <!-- Section -->\\n    <xpath expr=\\"section\\" position=\\"attributes\\">\\n        <attribute name=\\"class\\" add=\\"pt64 pb64\\" remove=\\"pt48 pb48\\" separator=\\" \\"/>\\n    </xpath>\\n\\n    <!-- Team #01 -->\\n    <xpath expr=\\"//div[hasclass('col-lg-6')]//img\\" position=\\"attributes\\">\\n        <attribute name=\\"class\\" remove=\\"rounded-circle\\" separator=\\" \\"/>\\n    </xpath>\\n    <!-- Team #01 - Title -->\\n    <xpath expr=\\"//div[hasclass('col-lg-6')]//h3\\" position=\\"replace\\" mode=\\"inner\\">\\n        <font style=\\"background-image: linear-gradient(135deg, var(--o-color-1) 0%, var(--o-color-5) 100%);\\" class=\\"text-gradient\\">Tony Fred</font>\\n    </xpath>\\n    <!-- Team #01 - Work Description -->\\n    <xpath expr=\\"//div[hasclass('col-lg-6')]//p\\" position=\\"replace\\" mode=\\"inner\\">\\n        Jefe de redacción\\n    </xpath>\\n    <!-- Team #01 - Paragraph -->\\n    <xpath expr=\\"//div[hasclass('col-lg-6')]//p[2]\\" position=\\"replace\\" mode=\\"inner\\">\\n        Tony, fundador y visionario principal, es la fuerza que mueve a la empresa. Le encanta participar en el desarrollo de software, en marketing y en estrategias de experiencias para los usuarios.\\n    </xpath>\\n    <!-- Team #01 - Img -->\\n    <xpath expr=\\"//img\\" position=\\"attributes\\">\\n        <attribute name=\\"src\\">/html_editor/image_shape/website.s_company_team_image_1/html_builder/geometric/geo_square_1.svg</attribute>\\n        <attribute name=\\"data-shape\\">html_builder/geometric/geo_square_1</attribute>\\n        <attribute name=\\"data-format-mimetype\\">image/webp</attribute>\\n        <attribute name=\\"data-file-name\\">uiface_1.svg</attribute>\\n        <attribute name=\\"data-shape-colors\\">;;;;</attribute>\\n    </xpath>\\n\\n    <!-- Team #02 -->\\n    <xpath expr=\\"//div[hasclass('col-lg-6')][2]//img\\" position=\\"attributes\\">\\n        <attribute name=\\"class\\" remove=\\"rounded-circle\\" separator=\\" \\"/>\\n    </xpath>\\n    <!-- Team #02 - Title -->\\n    <xpath expr=\\"//div[hasclass('col-lg-6')][2]//h3\\" position=\\"replace\\" mode=\\"inner\\">\\n        <font style=\\"background-image: linear-gradient(135deg, var(--o-color-1) 0%, var(--o-color-5) 100%);\\" class=\\"text-gradient\\">Mich Stark</font>\\n        <br/>\\n    </xpath>\\n    <!-- Team #02 - Work Description -->\\n    <xpath expr=\\"//div[hasclass('col-lg-6')][2]//p\\" position=\\"replace\\" mode=\\"inner\\">\\n        Periodista deportivo\\n    </xpath>\\n    <!-- Team #02 - Paragraph -->\\n    <xpath expr=\\"//div[hasclass('col-lg-6')][2]//p[2]\\" position=\\"replace\\" mode=\\"inner\\">\\n        A Mich le encanta asumir desafíos. Con su experiencia de varios años como periodista, quería unirse a un equipo que pusiera a las personas como los protagonistas de sus historias.\\n    </xpath>\\n    <!-- Team #02 - Img -->\\n    <xpath expr=\\"(//img)[2]\\" position=\\"attributes\\">\\n        <attribute name=\\"src\\">/html_editor/image_shape/website.s_company_team_image_2/html_builder/geometric/geo_square_2.svg</attribute>\\n        <attribute name=\\"data-