1	10	1	83	3	607	1	2	Café Guest	https://cafeguest.com	\N	\N	\N	\N	\N	\N	\N	\N	\N	\N	\N	\N	\N	\N	\N	b2b	\N	^/[^/]+/static/\n^/web/(css|js)/\n^/web/image\n^/web/content\n^/web/assets\n^/website/image/	<!DOCTYPE html>\r\n<html lang="es" class="scroll-smooth">\r\n<head>\r\n    <meta charset="UTF-8">\r\n    <meta name="viewport" content="width=device-width, initial-scale=1.0">\r\n    <title>Café Guest | Acogida y Sabor • Carta Digital</title>\r\n    <!-- Tailwind CSS -->\r\n    <script src="https://cdn.tailwindcss.com"></script>\r\n    <!-- Google Fonts: Playfair Display & Inter -->\r\n    <link rel="preconnect" href="https://fonts.googleapis.com">\r\n    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>\r\n    <link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600&family=Playfair+Display:ital,wght@0,500;0,600;0,700;1,400&display=swap" rel="stylesheet">\r\n    <!-- Lucide Icons -->\r\n    <script src="https://unpkg.com/lucide@latest"></script>\r\n\r\n    <script>\r\n        tailwind.config = {\r\n            theme: {\r\n                extend: {\r\n                    colors: {\r\n                        forest: {\r\n                            DEFAULT: '#1E3F20',\r\n                            light: '#2A542D',\r\n                            dark: '#142B15',\r\n                        },\r\n                        coffee: {\r\n                            DEFAULT: '#4A2E1B',\r\n                            light: '#69432A',\r\n                            dark: '#321E11',\r\n                        },\r\n                        cream: {\r\n                            DEFAULT: '#F5F0E6',\r\n                            light: '#FAF7F2',\r\n                            dark: '#E6DEC8',\r\n                        },\r\n                        gold: {\r\n                            DEFAULT: '#C89F65',\r\n                            light: '#DFC092',\r\n                            dark: '#A88047',\r\n                        }\r\n                    },\r\n                    fontFamily: {\r\n                        serif: ['"Playfair Display"', 'Georgia', 'serif'],\r\n                        sans: ['Inter', 'system-ui', 'sans-serif'],\r\n                    }\r\n                }\r\n            }\r\n        }\r\n    </script>\r\n\r\n    <style>\r\n        /* Animaciones suaves para filtrado de tarjetas */\r\n        @keyframes fadeInScale {\r\n            from {\r\n                opacity: 0;\r\n                transform: translateY(10px) scale(0.98);\r\n            }\r\n            to {\r\n                opacity: 1;\r\n                transform: translateY(0) scale(1);\r\n            }\r\n        }\r\n\r\n        .menu-card-animate {\r\n            animation: fadeInScale 0.35s cubic-bezier(0.16, 1, 0.3, 1) forwards;\r\n        }\r\n\r\n        /* Personalización sutil de barra de desplazamiento */\r\n        ::-webkit-scrollbar {\r\n            width: 8px;\r\n        }\r\n        ::-webkit-scrollbar-track {\r\n            background: #F5F0E6;\r\n        }\r\n        ::-webkit-scrollbar-thumb {\r\n            background: #C89F65;\r\n            border-radius: 4px;\r\n        }\r\n        ::-webkit-scrollbar-thumb:hover {\r\n            background: #4A2E1B;\r\n        }\r\n    </style>\r\n</head>\r\n	<body class="bg-cream text-coffee font-sans antialiased selection:bg-forest selection:text-cream">\r\n\r\n    <!-- Navegación Superior Fija -->\r\n    <header class="fixed top-0 left-0 right-0 z-50 bg-cream/95 backdrop-blur-md border-b border-coffee/10 transition-all duration-300">\r\n        <div class="max-w-6xl mx-auto px-4 sm:px-6 lg:px-8">\r\n            <div class="flex justify-between items-center h-20">\r\n                <!-- Logo / Marca -->\r\n                <a href="#" class="flex items-center gap-3 group">\r\n                    <div class="w-10 h-10 rounded-full bg-forest flex items-center justify-center text-cream shadow-sm group-hover:bg-coffee transition-colors">\r\n                        <i data-lucide="coffee" class="w-5 h-5 text-gold"></i>\r\n                    </div>\r\n                    <div>\r\n                        <span class="font-serif text-2xl font-bold tracking-tight text-forest block leading-none">Café Guest</span>\r\n                        <span class="text-[11px] uppercase tracking-widest text-coffee/70 font-medium">Coffee & Community</span>\r\n                    </div>\r\n                </a>\r\n\r\n                <!-- Enlaces Desktop -->\r\n                <nav class="hidden md:flex items-center space-x-8">\r\n                    <a href="#carta" class="text-sm font-medium text-coffee hover:text-forest transition-colors relative py-1 after:content-[''] after:absolute after:bottom-0 after:left-0 after:w-0 after:h-0.5 after:bg-forest hover:after:w-full after:transition-all">\r\n                        Nuestra Carta\r\n                    </a>\r\n                    <a href="#espacios" class="text-sm font-medium text-coffee hover:text-forest transition-colors relative py-1 after:content-[''] after:absolute after:bottom-0 after:left-0 after:w-0 after:h-0.5 after:bg-forest hover:after:w-full after:transition-all">\r\n                        Nuestros Espacios\r\n                    </a>\r\n                    <a href="#ubicacion" class="text-sm font-medium text-coffee hover:text-forest transition-colors relative py-1 after:content-[''] after:absolute after:bottom-0 after:left-0 after:w-0 after:h-0.5 after:bg-forest hover:after:w-full after:transition-all">\r\n                        Horarios y Ubicación\r\n                    </a>\r\n                </nav>\r\n\r\n                <!-- Botón Carta Rápido / Menú Móvil -->\r\n                <div class="flex items-center gap-3">\r\n                    <a href="#carta" class="hidden sm:inline-flex items-center gap-2 bg-forest hover:bg-forest-light text-cream text-sm font-medium px-5 py-2.5 rounded-full shadow-sm transition-all transform hover:-translate-y-0.5">\r\n                        <i data-lucide="book-open" class="w-4 h-4 text-gold"></i>\r\n                        <span>Ver Carta</span>\r\n                    </a>\r\n                    <button id="mobile-menu-btn" aria-label="Abrir menú" class="md:hidden p-2 rounded-lg text-coffee hover:bg-coffee/10 transition-colors">\r\n                        <i data-lucide="menu" class="w-6 h-6"></i>\r\n                    </button>\r\n                </div>\r\n            </div>\r\n        </div>\r\n\r\n        <!-- Menú Desplegable Móvil -->\r\n        <div id="mobile-menu" class="hidden md:hidden bg-cream-light border-b border-coffee/10 px-4 pt-2 pb-5 space-y-2 shadow-lg">\r\n            <a href="#carta" class="mobile-link block px-4 py-3 rounded-xl text-base font-medium text-coffee hover:bg-forest hover:text-cream transition-colors">\r\n                Nuestra Carta\r\n            </a>\r\n            <a href="#espacios" class="mobile-link block px-4 py-3 rounded-xl text-base font-medium text-coffee hover:bg-forest hover:text-cream transition-colors">\r\n                Nuestros Espacios\r\n            </a>\r\n            <a href="#ubicacion" class="mobile-link block px-4 py-3 rounded-xl text-base font-medium text-coffee hover:bg-forest hover:text-cream transition-colors">\r\n                Horarios y Ubicación\r\n            </a>\r\n        </div>\r\n    </header>\r\n\r\n    <!-- Sección Hero (Portada) -->\r\n    <section class="relative pt-32 pb-20 lg:pt-40 lg:pb-28 overflow-hidden bg-gradient-to-b from-cream-light via-cream to-cream-dark/50">\r\n        <!-- Elementos decorativos sutiles -->\r\n        <div class="absolute top-20 right-0 -mr-24 w-96 h-96 rounded-full bg-forest/5 blur-3xl pointer-events-none"></div>\r\n        <div class="absolute bottom-0 left-0 -ml-24 w-80 h-80 rounded-full bg-gold/10 blur-3xl pointer-events-none"></div>\r\n\r\n        <div class="max-w-4xl mx-auto px-4 sm:px-6 lg:px-8 text-center relative z-10">\r\n            <!-- Distintivo superior -->\r\n            <div class="inline-flex items-center gap-2 px-4 py-1.5 rounded-full bg-forest/10 border border-forest/20 text-forest text-xs font-semibold tracking-wider uppercase mb-6">\r\n                <i data-lucide="sparkles" class="w-3.5 h-3.5 text-gold-dark"></i>\r\n                <span>Cafetería de Especialidad & Obrador</span>\r\n            </div>\r\n\r\n            <!-- Título Principal -->\r\n            <h1 class="font-serif text-5xl sm:text-6xl lg:text-7xl font-bold text-forest tracking-tight mb-4">\r\n                Café Guest\r\n            </h1>\r\n\r\n            <!-- Subtítulo -->\r\n            <p class="font-serif italic text-xl sm:text-2xl text-coffee/90 mb-6">\r\n                Acogida y Sabor • Coffee & Community\r\n            </p>\r\n\r\n            <!-- Descripción -->\r\n            <p class="max-w-2xl mx-auto text-base sm:text-lg text-coffee/80 leading-relaxed mb-10">\r\n                Un rincón pensado para detener el reloj. Disfruta de granos seleccionados tostados con mimo, tostadas artesanales con masa madre y repostería casera recién salida del horno.\r\n            </p>\r\n\r\n            <!-- Botones de Acción -->\r\n            <div class="flex flex-col sm:flex-row items-center justify-center gap-4">\r\n                <a href="#carta" class="w-full sm:w-auto inline-flex items-center justify-center gap-2.5 bg-forest hover:bg-forest-light text-cream font-medium text-base px-8 py-4 rounded-full shadow-md hover:shadow-lg transition-all transform hover:-translate-y-0.5">\r\n                    <span>Ver la Carta</span>\r\n                    <i data-lucide="arrow-down" class="w-4 h-4 text-gold"></i>\r\n                </a>\r\n                <a href="#espacios" class="w-full sm:w-auto inline-flex items-center justify-center gap-2 bg-cream-light hover:bg-white text-coffee border border-coffee/20 font-medium text-base px-8 py-4 rounded-full transition-all">\r\n                    <span>Conoce el Local</span>\r\n                </a>\r\n            </div>\r\n        </div>\r\n    </section>\r\n\r\n    <!-- Sección Principal: La Carta Interactiva -->\r\n    <section id="carta" class="py-20 bg-cream-light border-t border-coffee/10 scroll-mt-16">\r\n        <div class="max-w-6xl mx-auto px-4 sm:px-6 lg:px-8">\r\n            \r\n            <!-- Encabezado de la Carta -->\r\n            <div class="text-center max-w-2xl mx-auto mb-12">\r\n                <span class="text-xs font-bold uppercase tracking-widest text-gold-dark block mb-2">Nuestra Propuesta</span>\r\n                <h2 class="font-serif text-3xl sm:text-4xl lg:text-5xl font-bold text-forest mb-4">\r\n                    La Carta de Café Guest\r\n                </h2>\r\n                <p class="text-coffee/75 text-sm sm:text-base">\r\n                    Preparamos cada taza y cada plato al momento con ingredientes frescos de proximidad. Filtra por categoría o busca tu favorito.\r\n                </p>\r\n            </div>\r\n\r\n            <!-- Barra de Controles: Buscador y Filtros -->\r\n            <div class="bg-cream p-4 sm:p-6 rounded-2xl border border-coffee/10 shadow-sm mb-10">\r\n                <div class="flex flex-col lg:flex-row lg:items-center justify-between gap-4">\r\n                    \r\n                    <!-- Botones de Categoría -->\r\n                    <div id="category-filters" class="flex flex-wrap items-center gap-2" role="tablist" aria-label="Categorías de la carta">\r\n                        <button data-category="todos" class="filter-btn active px-4 py-2.5 rounded-xl text-sm font-medium transition-all bg-forest text-cream shadow-sm">\r\n                            Todos\r\n                        </button>\r\n                        <button data-category="cafes" class="filter-btn px-4 py-2.5 rounded-xl text-sm font-medium transition-all bg-cream-light text-coffee hover:bg-coffee/10">\r\n                            ☕ Cafés\r\n                        </button>\r\n                        <button data-category="tostadas" class="filter-btn px-4 py-2.5 rounded-xl text-sm font-medium transition-all bg-cream-light text-coffee hover:bg-coffee/10">\r\n                            🥑 Tostadas\r\n                        </button>\r\n                        <button data-category="bocadillos" class="filter-btn px-4 py-2.5 rounded-xl text-sm font-medium transition-all bg-cream-light text-coffee hover:bg-coffee/10">\r\n                            🥖 Bocadillos\r\n                        </button>\r\n                        <button data-category="reposteria" class="filter-btn px-4 py-2.5 rounded-xl text-sm font-medium transition-all bg-cream-light text-coffee hover:bg-coffee/10">\r\n                            🥐 Repostería y Postres\r\n                        </button>\r\n                    </div>\r\n\r\n                    <!-- Buscador Rápido -->\r\n                    <div class="relative w-full lg:w-72">\r\n                        <div class="absolute inset-y-0 left-0 pl-3.5 flex items-center pointer-events-none">\r\n                            <i data-lucide="search" class="w-4 h-4 text-coffee/50"></i>\r\n                        </div>\r\n                        <input \r\n                            type="text" \r\n                            id="search-input" \r\n                            placeholder="Buscar café, aguacate, pollo..." \r\n                            class="w-full pl-10 pr-9 py-2.5 bg-cream-light border border-coffee/20 rounded-xl text-sm text-coffee placeholder-coffee/45 focus:outline-none focus:border-forest focus:ring-2 focus:ring-forest/15 transition-all"\r\n                        >\r\n                        <button id="clear-search" class="hidden absolute inset-y-0 right-0 pr-3 flex items-center text-coffee/50 hover:text-coffee" title="Limpiar búsqueda">\r\n                            <i data-lucide="x" class="w-4 h-4"></i>\r\n                        </button>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n            <!-- Contador de resultados -->\r\n            <div class="flex items-center justify-between mb-6 px-1">\r\n                <p id="results-count" class="text-xs font-medium text-coffee/65 uppercase tracking-wider">\r\n                    Mostrando todos los productos\r\n                </p>\r\n                <span class="text-xs text-coffee/60 hidden sm:inline">Precios con IVA incluido • Opciones sin lactosa y bebida vegetal disponibles</span>\r\n            </div>\r\n\r\n            <!-- Grid de Tarjetas de Productos -->\r\n            <div id="menu-grid" class="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">\r\n                <!-- Las tarjetas se renderizan dinámicamente con JavaScript -->\r\n            </div>\r\n\r\n            <!-- Estado Vacío (si la búsqueda no encuentra nada) -->\r\n            <div id="empty-state" class="hidden text-center py-16 px-4 bg-cream rounded-2xl border border-coffee/10">\r\n                <div class="w-14 h-14 rounded-full bg-coffee/10 flex items-center justify-center mx-auto mb-4 text-coffee">\r\n                    <i data-lucide="coffee" class="w-7 h-7"></i>\r\n                </div>\r\n                <h3 class="font-serif text-xl font-semibold text-forest mb-2">No encontramos coincidencias</h3>\r\n                <p class="text-sm text-coffee/75 max-w-md mx-auto mb-6">\r\n                    No hay platos o bebidas que coincidan con tu búsqueda actual. Prueba con otro ingrediente o explora toda la carta.\r\n                </p>\r\n                <button id="reset-filters-btn" class="inline-flex items-center gap-2 bg-forest text-cream text-sm font-medium px-5 py-2.5 rounded-full hover:bg-forest-light transition-colors">\r\n                    <i data-lucide="rotate-ccw" class="w-4 h-4"></i>\r\n                    <span>Mostrar toda la carta</span>\r\n                </button>\r\n            </div>\r\n\r\n        </div>\r\n    </section>\r\n\r\n    <!-- Sección Nuestros Espacios -->\r\n    <section id="espacios" class="py-20 bg-cream border-t border-coffee/10 scroll-mt-16">\r\n        <div class="max-w-6xl mx-auto px-4 sm:px-6 lg:px-8">\r\n            <div class="text-center max-w-2xl mx-auto mb-14">\r\n                <span class="text-xs font-bold uppercase tracking-widest text-gold-dark block mb-2">Tu lugar favorito</span>\r\n                <h2 class="font-serif text-3xl sm:text-4xl font-bold text-forest mb-4">\r\n                    Nuestros Espacios\r\n                </h2>\r\n                <p class="text-coffee/75 text-sm sm:text-base">\r\n                    Elige el ambiente que mejor encaje con tu momento del día. Disponemos de servicio completo en mesa en ambas zonas.\r\n                </p>\r\n            </div>\r\n\r\n            <div class="grid grid-cols-1 md:grid-cols-2 gap-8">\r\n                <!-- Tarjeta 1: Salón Principal -->\r\n                <div class="group bg-cream-light rounded-3xl overflow-hidden border border-coffee/15 shadow-sm hover:shadow-md transition-all flex flex-col">\r\n                    <div class="relative h-64 overflow-hidden bg-coffee">\r\n                        <img \r\n                            src="https://images.unsplash.com/photo-1554118811-1e0d58224f24?auto=format&fit=crop&w=900&q=80" \r\n                            alt="Interior cálido del Salón Principal de Café Guest" \r\n                            onerror="this.src='https://placehold.co/800x500/4A2E1B/F5F0E6?text=Sal%C3%B3n+Principal'"\r\n                            class="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500 opacity-90"\r\n                        >\r\n                        <div class="absolute inset-0 bg-gradient-to-t from-coffee-dark/80 via-transparent to-transparent"></div>\r\n                        <div class="absolute bottom-4 left-6 flex items-center gap-2">\r\n                            <span class="px-3 py-1 rounded-full bg-cream/95 text-forest text-xs font-semibold shadow-sm">\r\n                                Ambiente Interior\r\n                            </span>\r\n                        </div>\r\n                    </div>\r\n                    <div class="p-6 sm:p-8 flex-1 flex flex-col justify-between">\r\n                        <div>\r\n                            <div class="flex items-center justify-between mb-3">\r\n                                <h3 class="font-serif text-2xl font-bold text-forest">Salón Principal</h3>\r\n                                <i data-lucide="armchair" class="w-5 h-5 text-gold-dark"></i>\r\n                            </div>\r\n                            <p class="text-coffee/80 text-sm sm:text-base leading-relaxed mb-6">\r\n                                Un espacio acogedor con iluminación cálida, madera natural y el aroma constante a café recién molido. Ideal para charlar sin prisas, leer un libro o avanzar con tu portátil cómodamente.\r\n                            </p>\r\n                        </div>\r\n                        <div class="flex flex-wrap gap-3 pt-4 border-t border-coffee/10 text-xs font-medium text-coffee/75">\r\n                            <span class="inline-flex items-center gap-1.5 bg-cream px-3 py-1.5 rounded-lg">\r\n                                <i data-lucide="wifi" class="w-3.5 h-3.5 text-forest"></i> Wi-Fi Alta Velocidad\r\n                            </span>\r\n                            <span class="inline-flex items-center gap-1.5 bg-cream px-3 py-1.5 rounded-lg">\r\n                                <i data-lucide="plug" class="w-3.5 h-3.5 text-forest"></i> Enchufes en mesa\r\n                            </span>\r\n                            <span class="inline-flex items-center gap-1.5 bg-cream px-3 py-1.5 rounded-lg">\r\n                                <i data-lucide="thermometer-sun" class="w-3.5 h-3.5 text-forest"></i> Climatizado\r\n                            </span>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n\r\n                <!-- Tarjeta 2: Terraza -->\r\n                <div class="group bg-cream-light rounded-3xl overflow-hidden border border-coffee/15 shadow-sm hover:shadow-md transition-all flex flex-col">\r\n                    <div class="relative h-64 overflow-hidden bg-forest">\r\n                        <img \r\n                            src="https://images.unsplash.com/photo-1559925393-8be0ec4767c8?auto=format&fit=crop&w=900&q=80" \r\n                            alt="Terraza al aire libre de Café Guest" \r\n                            onerror="this.src='https://placehold.co/800x500/1E3F20/F5F0E6?text=Terraza+Caf%C3%A9+Guest'"\r\n                            class="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500 opacity-90"\r\n                        >\r\n                        <div class="absolute inset-0 bg-gradient-to-t from-forest-dark/80 via-transparent to-transparent"></div>\r\n                        <div class="absolute bottom-4 left-6 flex items-center gap-2">\r\n                            <span class="px-3 py-1 rounded-full bg-cream/95 text-forest text-xs font-semibold shadow-sm">\r\n                                Al Aire Libre\r\n                            </span>\r\n                        </div>\r\n                    </div>\r\n                    <div class="p-6 sm:p-8 flex-1 flex flex-col justify-between">\r\n                        <div>\r\n                            <div class="flex items-center justify-between mb-3">\r\n                                <h3 class="font-serif text-2xl font-bold text-forest">Terraza</h3>\r\n                                <i data-lucide="sun" class="w-5 h-5 text-gold-dark"></i>\r\n                            </div>\r\n                            <p class="text-coffee/80 text-sm sm:text-base leading-relaxed mb-6">\r\n                                Rodeada de plantas naturales y luz abierta, nuestra terraza es el punto de encuentro perfecto para disfrutar del sol de la mañana con un buen desayuno o desconectar al aire libre por la tarde.\r\n                            </p>\r\n                        </div>\r\n                        <div class="flex flex-wrap gap-3 pt-4 border-t border-coffee/10 text-xs font-medium text-coffee/75">\r\n                            <span class="inline-flex items-center gap-1.5 bg-cream px-3 py-1.5 rounded-lg">\r\n                                <i data-lucide="paw-print" class="w-3.5 h-3.5 text-forest"></i> Pet Friendly\r\n                            </span>\r\n                            <span class="inline-flex items-center gap-1.5 bg-cream px-3 py-1.5 rounded-lg">\r\n                                <i data-lucide="umbrella" class="w-3.5 h-3.5 text-forest"></i> Zona con sombra\r\n                            </span>\r\n                            <span class="inline-flex items-center gap-1.5 bg-cream px-3 py-1.5 rounded-lg">\r\n                                <i data-lucide="users" class="w-3.5 h-3.5 text-forest"></i> Mesas amplias\r\n                            </span>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </section>\r\n\r\n    <!-- Footer / Pie de página -->\r\n    <footer id="ubicacion" class="bg-forest text-cream pt-16 pb-10 scroll-mt-16">\r\n        <div class="max-w-6xl mx-auto px-4 sm:px-6 lg:px-8">\r\n            <div class="grid grid-cols-1 md:grid-cols-3 gap-10 pb-12 border-b border-cream/15">\r\n                \r\n                <!-- Columna 1: Marca -->\r\n                <div>\r\n                    <div class="flex items-center gap-3 mb-4">\r\n                        <div class="w-10 h-10 rounded-full bg-cream/10 flex items-center justify-center border border-gold/40">\r\n                            <i data-lucide="coffee" class="w-5 h-5 text-gold"></i>\r\n                        </div>\r\n                        <div>\r\n                            <span class="font-serif text-2xl font-bold text-cream block leading-none">Café Guest</span>\r\n                            <span class="text-[11px] uppercase tracking-widest text-gold-light">Acogida y Sabor</span>\r\n                        </div>\r\n                    </div>\r\n                    <p class="text-cream/75 text-sm leading-relaxed mb-6">\r\n                        Tu cafetería de barrio con alma de especialidad. Un lugar donde cada invitado se siente como en casa.\r\n                    </p>\r\n                    <div class="flex items-center gap-3">\r\n                        <a href="#carta" aria-label="Instagram" class="w-9 h-9 rounded-full bg-cream/10 hover:bg-gold hover:text-forest flex items-center justify-center transition-colors">\r\n                            <i data-lucide="instagram" class="w-4 h-4"></i>\r\n                        </a>\r\n                        <a href="#ubicacion" aria-label="Ubicación" class="w-9 h-9 rounded-full bg-cream/10 hover:bg-gold hover:text-forest flex items-center justify-center transition-colors">\r\n                            <i data-lucide="map-pin" class="w-4 h-4"></i>\r\n                        </a>\r\n                    </div>\r\n                </div>\r\n\r\n                <!-- Columna 2: Horarios -->\r\n                <div>\r\n                    <h4 class="font-serif text-lg font-semibold text-gold-light mb-4 flex items-center gap-2">\r\n                        <i data-lucide="clock" class="w-4 h-4 text-gold"></i>\r\n                        <span>Horarios de Apertura</span>\r\n                    </h4>\r\n                    <ul class="space-y-2.5 text-sm text-cream/85">\r\n                        <li class="flex justify-between border-b border-cream/10 pb-2">\r\n                            <span>Lunes a Viernes</span>\r\n                            <span class="font-medium text-cream">07:30 – 20:30</span>\r\n                        </li>\r\n                        <li class="flex justify-between border-b border-cream/10 pb-2">\r\n                            <span>Sábados</span>\r\n                            <span class="font-medium text-cream">08:30 – 21:00</span>\r\n                        </li>\r\n                        <li class="flex justify-between pb-1">\r\n                            <span>Domingos y Festivos</span>\r\n                            <span class="font-medium text-gold-light">09:00 – 15:00</span>\r\n                        </li>\r\n                    </ul>\r\n                </div>\r\n\r\n                <!-- Columna 3: Contacto y Dirección -->\r\n                <div>\r\n                    <h4 class="font-serif text-lg font-semibold text-gold-light mb-4 flex items-center gap-2">\r\n                        <i data-lucide="map-pin" class="w-4 h-4 text-gold"></i>\r\n                        <span>Dónde Estamos</span>\r\n                    </h4>\r\n                    <ul class="space-y-3 text-sm text-cream/85">\r\n                        <li class="flex items-start gap-3">\r\n                            <i data-lucide="navigation" class="w-4 h-4 text-gold shrink-0 mt-1"></i>\r\n                            <span>Calle de la Acogida, 24<br>46001 Valencia, España</span>\r\n                        </li>\r\n                        <li class="flex items-center gap-3">\r\n                            <i data-lucide="phone" class="w-4 h-4 text-gold shrink-0"></i>\r\n                            <span>+34 960 123 456</span>\r\n                        </li>\r\n                        <li class="flex items-center gap-3">\r\n                            <i data-lucide="mail" class="w-4 h-4 text-gold shrink-0"></i>\r\n                            <span>hola@cafeguest.es</span>\r\n                        </li>\r\n                    </ul>\r\n                </div>\r\n\r\n            </div>\r\n\r\n            <!-- Copyright -->\r\n            <div class="pt-8 flex flex-col sm:flex-row items-center justify-between text-xs text-cream/60 gap-4">\r\n                <p>&copy; <span id="current-year"></span> Café Guest. Todos los derechos reservados.</p>\r\n                <p>Coffee & Community • Hecho con cariño</p>\r\n            </div>\r\n        </div>\r\n    </footer>\r\n\r\n    <!-- Lógica JavaScript de la Carta Interactiva -->\r\n    <script>\r\n        // Base de datos de productos de Café Guest\r\n        const menuItems = [\r\n            // CAFÉS\r\n            {\r\n                id: 1,\r\n                name: "Espresso Doble",\r\n                category: "cafes",\r\n                categoryLabel: "Café",\r\n                price: "2,20 €",\r\n                description: "Extracción equilibrada de nuestro grano 100% Arábica de tueste medio con notas a cacao y avellana.",\r\n                tag: "100% Arábica",\r\n                tagColor: "bg-coffee/10 text-coffee"\r\n            },\r\n            {\r\n                id: 2,\r\n                name: "Flat White",\r\n                category: "cafes",\r\n                categoryLabel: "Café",\r\n                price: "3,10 €",\r\n                description: "Doble carga de espresso cubierta con una fina capa de leche sedosa microespumada.",\r\n                tag: "Favorito",\r\n                tagColor: "bg-gold/25 text-coffee-dark"\r\n            },\r\n            {\r\n                id: 3,\r\n                name: "Cappuccino Guest",\r\n                category: "cafes",\r\n                categoryLabel: "Café",\r\n                price: "3,20 €",\r\n                description: "Nuestra receta de la casa: espresso intenso, crema densa de leche y un toque sutil de cacao puro espolvoreado.",\r\n                tag: "Especialidad",\r\n                tagColor: "bg-forest/15 text-forest"\r\n            },\r\n            {\r\n                id: 4,\r\n                name: "Latte Macchiato",\r\n                category: "cafes",\r\n                categoryLabel: "Café",\r\n                price: "3,00 €",\r\n                description: "Leche cremosa vaporizada manchada con un shot de café de especialidad. Disponible con bebida de avena o soja.",\r\n                tag: "Opción Vegetal",\r\n                tagColor: "bg-forest/10 text-forest"\r\n            },\r\n            {\r\n                id: 5,\r\n                name: "Cold Brew Tónica y Naranja",\r\n                category: "cafes",\r\n                categoryLabel: "Café",\r\n                price: "3,80 €",\r\n                description: "Café infusionado en frío durante 18 horas, servido con hielo, tónica artesanal y una rodaja de naranja deshidratada.",\r\n                tag: "Refrescante",\r\n                tagColor: "bg-gold/25 text-coffee-dark"\r\n            },\r\n\r\n            // TOSTADAS\r\n            {\r\n                id: 6,\r\n                name: "Tostada de Aguacate y Huevo Poché",\r\n                category: "tostadas",\r\n                categoryLabel: "Tostada",\r\n                price: "6,50 €",\r\n                description: "Pan de masa madre tostado, aguacate laminado, huevo poché ecológico, semillas de sésamo y aceite de oliva virgen extra.",\r\n                tag: "Vegetariano",\r\n                tagColor: "bg-forest/15 text-forest"\r\n            },\r\n            {\r\n                id: 7,\r\n                name: "Tostada de Tomate Triturado y Jamón Ibérico",\r\n                category: "tostadas",\r\n                categoryLabel: "Tostada",\r\n                price: "5,90 €",\r\n                description: "Rebanada rústica crujiente con tomate natural rallado al momento, AOVE de primera prensada y virutas de jamón ibérico.",\r\n                tag: "Clásico",\r\n                tagColor: "bg-coffee/10 text-coffee"\r\n            },\r\n            {\r\n                id: 8,\r\n                name: "Tostada de Ricotta, Higos y Miel",\r\n                category: "tostadas",\r\n                categoryLabel: "Tostada",\r\n                price: "6,20 €",\r\n                description: "Base cremosa de queso ricotta artesanal, higos frescos de temporada, nueces tostadas y un hilo de miel de azahar.",\r\n                tag: "Vegetariano",\r\n                tagColor: "bg-forest/15 text-forest"\r\n            },\r\n\r\n            // BOCADILLOS\r\n            {\r\n                id: 9,\r\n                name: "Bocadillo de Pollo Crujiente y Alioli Suave",\r\n                category: "bocadillos",\r\n                categoryLabel: "Bocadillo",\r\n                price: "7,40 €",\r\n                description: "Pan chapata rústico con pechuga de pollo marinada crujiente, brotes tiernos, tomate seco y alioli suave de hierbas.",\r\n                tag: "Especialidad",\r\n                tagColor: "bg-gold/25 text-coffee-dark"\r\n            },\r\n            {\r\n                id: 10,\r\n                name: "Bocadillo Vegetal de Queso de Cabra",\r\n                category: "bocadillos",\r\n                categoryLabel: "Bocadillo",\r\n                price: "6,90 €",\r\n                description: "Pan de cereales con medallón de queso de cabra templado, cebolla caramelizada lenta, rúcula fresca y pesto de albahaca.",\r\n                tag: "Vegetariano",\r\n                tagColor: "bg-forest/15 text-forest"\r\n            },\r\n            {\r\n                id: 11,\r\n                name: "Bikini Trufado de Jamón y Queso",\r\n                category: "bocadillos",\r\n                categoryLabel: "Bocadillo",\r\n                price: "5,80 €",\r\n                description: "Pan brioche dorado a la plancha con mantequilla, jamón cocido braseado, queso Havarti fundido y crema de trufa negra.",\r\n                tag: "Caliente",\r\n                tagColor: "bg-coffee/10 text-coffee"\r\n            },\r\n\r\n            // REPOSTERÍA Y POSTRES\r\n            {\r\n                id: 12,\r\n                name: "Croissant de Mantequilla Artesanal",\r\n                category: "reposteria",\r\n                categoryLabel: "Repostería",\r\n                price: "2,60 €",\r\n                description: "Hojaldre ligero y crujiente elaborado con mantequilla francesa de alta calidad, horneado cada mañana.",\r\n                tag: "Recién horneado",\r\n                tagColor: "bg-gold/25 text-coffee-dark"\r\n            },\r\n            {\r\n                id: 13,\r\n                name: "Tarta de Zanahoria Casera",\r\n                category: "reposteria",\r\n                categoryLabel: "Postre",\r\n                price: "4,50 €",\r\n                description: "Bizcocho esponjoso especiado con canela, nueces y zanahoria fresca, cubierto con frosting suave de queso crema.",\r\n                tag: "Casero",\r\n                tagColor: "bg-forest/15 text-forest"\r\n            },\r\n            {\r\n                id: 14,\r\n                name: "Roll de Canela y Cardamomo",\r\n                category: "reposteria",\r\n                categoryLabel: "Repostería",\r\n                price: "3,40 €",\r\n                description: "Bollo tierno trenzado con azúcar moreno, canela de Ceilán y un toque aromático de cardamomo recién molido.",\r\n                tag: "Recién horneado",\r\n                tagColor: "bg-gold/25 text-coffee-dark"\r\n            },\r\n            {\r\n                id: 15,\r\n                name: "Brownie de Chocolate 70% y Nueces",\r\n                category: "reposteria",\r\n                categoryLabel: "Postre",\r\n                price: "4,10 €",\r\n                description: "Intenso en cacao, húmedo por dentro y crujiente por fuera. Ideal para acompañar con un Espresso o Flat White.",\r\n                tag: "Casero",\r\n                tagColor: "bg-coffee/10 text-coffee"\r\n            }\r\n        ];\r\n\r\n        // Estado de filtros\r\n        let currentCategory = 'todos';\r\n        let currentSearch = '';\r\n\r\n        // Referencias al DOM\r\n        const menuGrid = document.getElementById('menu-grid');\r\n        const emptyState = document.getElementById('empty-state');\r\n        const resultsCount = document.getElementById('results-count');\r\n        const searchInput = document.getElementById('search-input');\r\n        const clearSearchBtn = document.getElementById('clear-search');\r\n        const filterBtns = document.querySelectorAll('.filter-btn');\r\n        const resetFiltersBtn = document.getElementById('reset-filters-btn');\r\n        const mobileMenuBtn = document.getElementById('mobile-menu-btn');\r\n        const mobileMenu = document.getElementById('mobile-menu');\r\n\r\n        // Función para renderizar las tarjetas del menú\r\n        function renderMenu() {\r\n            const normalizedSearch = currentSearch.toLowerCase().trim();\r\n\r\n            const filteredItems = menuItems.filter(item => {\r\n                const matchesCategory = currentCategory === 'todos' || item.category === currentCategory;\r\n                const matchesSearch = \r\n                    item.name.toLowerCase().includes(normalizedSearch) ||\r\n                    item.description.toLowerCase().includes(normalizedSearch) ||\r\n                    item.tag.toLowerCase().includes(normalizedSearch);\r\n\r\n                return matchesCategory && matchesSearch;\r\n            });\r\n\r\n            // Actualizar contador\r\n            if (filteredItems.length === 1) {\r\n                resultsCount.textContent = "Mostrando 1 producto";\r\n            } else {\r\n                resultsCount.textContent = `Mostrando ${filteredItems.length} productos`;\r\n            }\r\n\r\n            // Limpiar grid\r\n            menuGrid.innerHTML = '';\r\n\r\n            if (filteredItems.length === 0) {\r\n                menuGrid.classList.add('hidden');\r\n                emptyState.classList.remove('hidden');\r\n                return;\r\n            }\r\n\r\n            menuGrid.classList.remove('hidden');\r\n            emptyState.classList.add('hidden');\r\n\r\n            // Crear tarjetas\r\n            filteredItems.forEach((item, index) => {\r\n                const card = document.createElement('article');\r\n                card.className = 'menu-card-animate bg-cream rounded-2xl p-6 border border-coffee/10 hover:border-gold transition-all duration-300 shadow-sm hover:shadow-md flex flex-col justify-between group';\r\n                card.style.animationDelay = `${index * 0.04}s`;\r\n\r\n                card.innerHTML = `\r\n                    <div>\r\n                        <div class="flex items-center justify-between gap-2 mb-3">\r\n                            <span class="text-[11px] font-semibold uppercase tracking-wider px-2.5 py-1 rounded-full ${item.tagColor}">\r\n                                ${item.tag}\r\n                            </span>\r\n                            <span class="text-xs font-medium text-coffee/50">\r\n                                ${item.categoryLabel}\r\n                            </span>\r\n                        </div>\r\n                        <h3 class="font-serif text-xl font-bold text-forest group-hover:text-coffee transition-colors mb-2">\r\n                            ${item.name}\r\n                        </h3>\r\n                        <p class="text-sm text-coffee/75 leading-relaxed mb-5">\r\n                            ${item.description}\r\n                        </p>\r\n                    </div>\r\n                    <div class="pt-4 border-t border-coffee/10 flex items-center justify-between">\r\n                        <span class="text-xs text-coffee/55 font-medium">Preparado al momento</span>\r\n                        <span class="font-sans text-lg font-bold text-forest bg-cream-light px-3.5 py-1 rounded-xl border border-coffee/10">\r\n                            ${item.price}\r\n                        </span>\r\n                    </div>\r\n                `;\r\n\r\n                menuGrid.appendChild(card);\r\n            });\r\n        }\r\n\r\n        // Eventos de botones de categoría\r\n        filterBtns.forEach(btn => {\r\n            btn.addEventListener('click', () => {\r\n                // Quitar clase activa de todos\r\n                filterBtns.forEach(b => {\r\n                    b.classList.remove('bg-forest', 'text-cream', 'shadow-sm');\r\n                    b.classList.add('bg-cream-light', 'text-coffee', 'hover:bg-coffee/10');\r\n                });\r\n\r\n                // Activar el seleccionado\r\n                btn.classList.remove('bg-cream-light', 'text-coffee', 'hover:bg-coffee/10');\r\n                btn.classList.add('bg-forest', 'text-cream', 'shadow-sm');\r\n\r\n                currentCategory = btn.getAttribute('data-category');\r\n                renderMenu();\r\n            });\r\n        });\r\n\r\n        // Evento de búsqueda en tiempo real\r\n        searchInput.addEventListener('input', (e) => {\r\n            currentSearch = e.target.value;\r\n            if (currentSearch.length > 0) {\r\n                clearSearchBtn.classList.remove('hidden');\r\n            } else {\r\n                clearSearchBtn.classList.add('hidden');\r\n            }\r\n            renderMenu();\r\n        });\r\n\r\n        // Limpiar búsqueda\r\n        clearSearchBtn.addEventListener('click', () => {\r\n            searchInput.value = '';\r\n            currentSearch = '';\r\n            clearSearchBtn.classList.add('hidden');\r\n            searchInput.focus();\r\n            renderMenu();\r\n        });\r\n\r\n        // Botón restablecer desde estado vacío\r\n        resetFiltersBtn.addEventListener('click', () => {\r\n            searchInput.value = '';\r\n            currentSearch = '';\r\n            clearSearchBtn.classList.add('hidden');\r\n            currentCategory = 'todos';\r\n\r\n            filterBtns.forEach(b => {\r\n                if (b.getAttribute('data-category') === 'todos') {\r\n                    b.classList.remove('bg-cream-light', 'text-coffee', 'hover:bg-coffee/10');\r\n                    b.classList.add('bg-forest', 'text-cream', 'shadow-sm');\r\n                } else {\r\n                    b.classList.remove('bg-forest', 'text-cream', 'shadow-sm');\r\n                    b.classList.add('bg-cream-light', 'text-coffee', 'hover:bg-coffee/10');\r\n                }\r\n            });\r\n\r\n            renderMenu();\r\n        });\r\n\r\n        // Menú móvil\r\n        mobileMenuBtn.addEventListener('click', () => {\r\n            mobileMenu.classList.toggle('hidden');\r\n        });\r\n\r\n        document.querySelectorAll('.mobile-link').forEach(link => {\r\n            link.addEventListener('click', () => {\r\n                mobileMenu.classList.add('hidden');\r\n            });\r\n        });\r\n\r\n        // Año actual en el footer y carga inicial\r\n        document.getElementById('current-year').textContent = new Date().getFullYear();\r\n        lucide.createIcons();\r\n        renderMenu();\r\n    </script>\r\n</body>\r\n</html>	\N	t	\N	t	t	f	\N	\N	2026-11-24 08:36:19.337065	2026-11-25 09:42:07.342941
